import * as sb from '@vside/microsoft-servicebroker';
import { readSubstream, writeSubstream } from 'nerdbank-streams';
import { IGuestChannelService } from '../_new_/abstractions/Interfaces';
import { ClientToHostHandshake, HostToClientHandshake } from './handshakeContracts';
import { Signal } from '@vs/vso-rpc';
import { CancellationToken } from 'vscode';
import { traceSource as trace } from '@vs/vscode-command-framework';

const protocolMajorVersion: number = 2;
const protocolMinorVersion: number = 0;

/**
 * Initializes a service broker from a shared pipe
 * @param channelService The channel service to use in requesting a stream
 */
export async function getServiceBrokerForLiveShare(channelService: IGuestChannelService, cancellationToken?: CancellationToken): Promise<sb.IServiceBroker> {
    const socket = await channelService.connectToChannelAsync('IServiceBroker', cancellationToken);
    if (!socket) {
        return null;
    }

    try {
        socket.write(Buffer.from([protocolMajorVersion, protocolMinorVersion]));
        const clientInfo: ClientToHostHandshake = {
            IsNexusClient: true,
        };
        const jsonStream = writeSubstream(socket);
        const writeSignal = new Signal<void>();
        const clientInfoBytes = Buffer.from(JSON.stringify(clientInfo), 'utf8');
        jsonStream.write(clientInfoBytes, () => {
            jsonStream.end();
            writeSignal.complete();
        });

        await writeSignal.withCancellation(cancellationToken);
        const version = await readFromSocket(socket, 2);
        if (version[0] !== protocolMajorVersion) {
            trace.error('Service Broker protocol version from host did not match supported version.');
            return null;
        }

        const readStream = readSubstream(socket);
        const hostInfoBytes = await readFromSocket(readStream);
        const hostInfo = JSON.parse(hostInfoBytes.toString('utf8')) as HostToClientHandshake;

        const remoteServiceBroker = await sb.RemoteServiceBroker.connectToMultiplexingDuplex(socket);

        return remoteServiceBroker;
    } catch (err) {
        trace.error('Error getting Service Broker', err);
        throw err;
    }
}


async function readFromSocket(stream: NodeJS.ReadableStream, size?: number, cancellationToken?: CancellationToken): Promise<Buffer> {
    const endSignal = new Signal<void>();
    while (true) {
        const readBuffer = stream.read(size) as Buffer;
        if (readBuffer) {
            return readBuffer;
        }

        // Arrange to wait for more bytes or the end of stream
        stream.once('readable', () => {
            endSignal.complete();
        });
        stream.once('end', () => {
            endSignal.complete();
        });

        await endSignal.withCancellation(cancellationToken);
    }
}