import { IBreakpointManager } from './IBreakpointManager';
import { IShareBreakpointManager } from './IShareBreakpointManager';

export class ShareBreakpointManager implements IShareBreakpointManager {
    constructor (
        private builder: IBreakpointManager) {
    }

    public init(): Promise<void> {
        return this.builder.init(true);
    }

    public dispose(): Promise<void> {
        return this.builder.dispose();
    }
}