import * as os from 'os';
import * as url from 'url';
import * as path from 'path';
import * as vscode from 'vscode';

import { traceSource, fileAccess } from '@vs/vscode-command-framework';
import { TraceFormat, LoggerSettings } from '@vs/vso-logging';
import { vsls } from '@vs/liveshare-core';
import * as rc from './remoteConfig';
import { loadJSON } from './utils/loadJSON';
import { EXTENSION_ROOT_PATH } from './constants';

const modifiedInternalSettingsFilePath = process.env.VSLS_SETTINGS_FILE || path.resolve(EXTENSION_ROOT_PATH, './modifiedInternalSettings.json');

function getModifiedInternalSettings() {
    let settings = {};

    try {
        settings = loadJSON(modifiedInternalSettingsFilePath);
    } catch (e) {
        // Don't show the "What's New" toast in the case of a corrupted modifiedInternalSettings.json.
        (settings as any).whatsNewUri = '';
        traceSource.info('Failed to parse modifiedInternalSettings.json');
    }

    return settings;
}

const modifiedInternalSettings = getModifiedInternalSettings();

const unmodifiedInternalSettings = loadJSON(path.resolve(EXTENSION_ROOT_PATH, './internalSettings.json'));

const internalSettings = Object.assign({}, unmodifiedInternalSettings, modifiedInternalSettings);

class InternalConfig {
    private static singleton: InternalConfig;
    private internalSettings: { [key: string]: object } = internalSettings;
    private modifiedInternalSettings: { [key: string]: object } = modifiedInternalSettings;
    private userSettings: { [key: string]: object };

    constructor() {
        this.userSettings = {};
    }

    public static get Instance(): InternalConfig {
        if (!InternalConfig.singleton) {
            InternalConfig.singleton = new InternalConfig();
        }
        return InternalConfig.singleton;
    }

    public async initAsync(context: vscode.ExtensionContext, userSettingsKeyString: string): Promise<void> {
        if (typeof this.get<boolean>('isInternal') === 'undefined') {
            this.save('isInternal', isInternal(), false);
        }
        if (typeof this.get<boolean>('canCollectPII') === 'undefined') {
            this.save('canCollectPII', canCollectPII(), false);
        }
        LoggerSettings.disableObfuscation = this.get<boolean>('canCollectPII') || false;
        await this.readUserSettings(userSettingsKeyString);
        // In case this setting has changed after reading user settings
        LoggerSettings.disableObfuscation = this.get<boolean>('canCollectPII') || false;
    }

    public async readUserSettings(userSettingsKeyString: string) {
        let userSettingsFilePath = path.join(os.homedir(), internalSettings[userSettingsKeyString]);
        // Check that the file exists
        try {
            await fileAccess.accessAsync(userSettingsFilePath);
        } catch (e) {
            traceSource.info('Did not find user settings at ' + TraceFormat.formatPath(userSettingsFilePath));
            return;
        }
        try {
            this.userSettings = await fileAccess.readJson(userSettingsFilePath);
        } catch (e) {
            traceSource.info('User settings are not valid JSON');
            return;
        }
    }

    private async saveInternalSettings(): Promise<void> {
        await fileAccess.writeJson(modifiedInternalSettingsFilePath, this.modifiedInternalSettings, { spaces: '\t' });
    }

    public get<T>(keyString: string): T | undefined {
        // Internal user settings, when set, override both remote settings and internal defaults.
        let value = this.userSettings[keyString] as any as T | undefined;

        if (value === undefined) {
            // Remote defaults, when set, override internal defaults.
            value = rc.RemoteConfig.getDefault<T>(keyString);
        }

        if (value === undefined) {
            value = this.internalSettings[keyString] as any as T;
        }

        return value;
    }

    public getUserSettings(): vsls.UserSettings {
        return Object.assign(this.internalSettings, this.userSettings);
    }

    public async save(keyString: string, value: any, delaySaveToDisk: boolean): Promise<void> {
        this.internalSettings[keyString] = value;
        this.modifiedInternalSettings[keyString] = value;
        if (!delaySaveToDisk) {
            await this.saveInternalSettings();
        }
    }

    public getUri(keyString: string): url.Url | undefined {
        let value = this.get<string>(keyString);
        if (!value) {
            return undefined;
        }

        try {
            return url.parse(value);
        } catch (e) {
            return undefined;
        }
    }
}

const internalConfigInstance = InternalConfig.Instance;
export { internalConfigInstance as InternalConfig };

const canCollectPIIDomains = [
    'redmond.corp.microsoft.com',
    'northamerica.corp.microsoft.com',
    'fareast.corp.microsoft.com',
    'ntdev.corp.microsoft.com',
    'wingroup.corp.microsoft.com',
    'southpacific.corp.microsoft.com',
    'wingroup.windeploy.ntdev.microsoft.com',
    'ddnet.microsoft.com'];

function canCollectPII(): boolean {
    let userDomain = process.env.USERDNSDOMAIN ? process.env.USERDNSDOMAIN.toLowerCase() : '';
    return canCollectPIIDomains.indexOf(userDomain) >= 0;
}

function isInternal(): boolean {
    let userDomain = process.env.USERDNSDOMAIN ? process.env.USERDNSDOMAIN.toLowerCase() : '';
    return userDomain.endsWith('microsoft.com');
}
