import * as path from 'path';
import * as os from 'os';
import { fileAccess, traceSource } from '@vs/vscode-command-framework';

import { ExtensionUtil } from '../../extensionUtil';
import * as child_process from 'child_process';
import * as process from 'process';
import * as vscode from 'vscode';
import * as config from '../../config';
import * as util from '../../util';
import { sync as mkdirpSync } from 'mkdirp';
import { EXTENSION_ROOT_PATH } from '../../constants';
import { OSPlatform } from '../../osPlatform';
import { vsls, ClipboardUtil, ExtensionUtil as ExtensionUtilCore } from '@vs/liveshare-core';

/**
 * Interacts with the Cascade VSCode launcher.
 */
export class Launcher {
    private static readonly nodeModulesPath = path.join(EXTENSION_ROOT_PATH, 'node_modules');
    private static readonly launcherOSXPath = path.join(Launcher.nodeModulesPath, '@vsliveshare', 'vscode-launcher-osx');
    private static readonly launcherWinPath = path.join(Launcher.nodeModulesPath, '@vsliveshare', 'vscode-launcher-win');
    private static readonly launcherLinuxPath = path.join(Launcher.nodeModulesPath, '@vsliveshare', 'vscode-launcher-linux');
    private static readonly launcherOptions = Launcher.getLauncherOptions();
    private static readonly trace = traceSource.withName(vsls.TraceSources.ClientLauncher);
    private static readonly manualJoinUrl: string = 'https://aka.ms/vsls-docs/manual-join';
    private static readonly JOIN_FILE_LIFESPAN: number = 30 * 1000;

    /**
     * Installs and starts the launcher. Returns `true` if installation succeeded.
     */
    public static async run(userInitiated: boolean, installInitiated: boolean = false): Promise<boolean> {
        const [command, args] = await Launcher.getLauncherCommand(userInitiated, installInitiated);

        if (!command) {
            // Launcher probably already set up.
            // TODO: be more explicit about this and show notification to user
            // Right now, the default "Launcher successfully installed" message will show.
            return true;
        }
        // If sudo is required, use a terminal instead
        if ((await Launcher.launcherOptions).sudoRequired && (config.get(config.Key.showLauncherInstallNotification) || userInitiated)) {
            return await Launcher.presentSudoTerminalCommand(command, args, userInitiated);
        } else {
            const cp = child_process.spawn(command, args);

            return await new Promise<boolean>((resolve, reject) => {
                cp.stdout.on('data', (data: Buffer) => {
                    Launcher.trace.verbose(data.toString().trim());
                });

                cp.stderr.on('data', (data: Buffer) => {
                    Launcher.trace.error(data.toString().trim());
                });

                cp.on('error', (err: Error) => {
                    Launcher.trace.error('Launcher failed with error: ' + err);
                });

                cp.on('close', (exitCode, signal) => {
                    if (exitCode === 0) {
                        resolve(true);
                    } else {
                        // Non-zero exit code means something went wrong during script execution.
                        // 127 can mean missing dependencies, but this is handled in the setup method
                        if (!exitCode) {
                            reject(new Error('Command failed to execute and terminated with signal: ' + signal));
                        } else {
                            reject(Launcher.getErrorForExitCode(exitCode));
                        }
                    }

                    Launcher.trace.info(
                        'Launcher terminated with exit code: ' + exitCode + ' and signal ' + signal);
                });
            });
        }

    }

    private static async presentSudoTerminalCommand(command: string, args: string[], userInitiated: boolean = false): Promise<boolean> {
        const installResponse = 'Install';
        const copyInsteadResponse = 'Copy instead';
        const neverShowAgainResponse = 'Never show again';
        const result = await vscode.window.showInformationMessage(
            'To support joining a session using a browser link, we need permission to run an installer on your system. Your OS may ask you for your admin (sudo) password in a terminal. Install now?',
            { title: installResponse },
            { title: copyInsteadResponse },
            !userInitiated ? { title: neverShowAgainResponse } : undefined
        );

        if (!result) {
            return false;
        }

        switch (result.title) {
            case installResponse:
                const exitCode = await ExtensionUtil.executeCommandInTerminal('Launcher installation (VS Live Share)', command, args);
                if (exitCode === 0) {
                    if (!userInitiated) {
                        // This is an exception case where we prompt for a sudo password and need to let
                        // users know it has finished successfully even if not user initiated. The user initiated
                        // message is handled in the setup method. However, we should not await or the message
                        // has to be dismissed before everything else kicks in.
                        vscode.window.showInformationMessage('Browser link launcher successfully installed.');
                    }
                    return true;
                } else {
                    // Non-zero exit code means something went wrong during script execution.
                    // 127 can mean missing dependencies, but this is handled in the setup method
                    if (!exitCode) {
                        throw new Error('Command failed to execute.');
                    }
                    throw Launcher.getErrorForExitCode(exitCode);
                }
            case copyInsteadResponse:
                const fullCommand = `"${command}" ${(args.length > 0 ? ' "' + args.join('" "') + '"' : '')}`;
                if (await new ClipboardUtil().copyToClipboardAsync(fullCommand)) {
                    // Don't await, or message has to be dismissed before execution continues.
                    vscode.window.showInformationMessage(
                        'Browser link launcher install command copied to clipboard.');
                } else {
                    // Don't await, or message has to be dismissed before execution continues.
                    vscode.window.showInputBox({
                        prompt: 'Browser link launcher install command',
                        value: fullCommand,
                        ignoreFocusOut: true,
                    });
                }
                return false;
            case neverShowAgainResponse:
                await config.save(config.Key.showLauncherInstallNotification, false);
                // Don't await, or message has to be dismissed before execution continues.
                vscode.window.showInformationMessage('You can run the "Live Share: Launcher Setup" command to complete the integration later.');
                return false;
            default:
                return false;
        }
    }

    /**
     * Reads the json content of cascade.json.
     * In case of an error, it returns undefined.
     */
    public static async readCascadeURL(): Promise<string> {
        try {
            const jsonFileContents: string = await Launcher.readFileContents((await Launcher.launcherOptions).cascadeLaunchUrlFile);
            const launchUrlFileModificationTime = await util.getModificationTime((await Launcher.launcherOptions).cascadeLaunchUrlFile);
            const fileAge = util.getTimestampAge(launchUrlFileModificationTime);

            await Launcher.safelyDeleteCascadeUrlFile();

            Launcher.trace.info(`[cascade.json]: age: ${fileAge}`);
            if (fileAge <= Launcher.JOIN_FILE_LIFESPAN) {
                const info: CascadeInfo = JSON.parse(jsonFileContents) as CascadeInfo;
                return info.url;
            }
            Launcher.trace.info(`[cascade.json]: Join workspace url is older than ${Launcher.JOIN_FILE_LIFESPAN}ms so was ignored.`);
        } catch (e) {
            Launcher.trace.error(e.message);
        }
    }

    /**
     * Deletes the contents of cascade.json.
     */
    public static async deleteCascadeUrlFile(): Promise<void> {
        return fileAccess.unlinkAsync((await Launcher.launcherOptions).cascadeLaunchUrlFile);
    }

    public static async safelyDeleteCascadeUrlFile(): Promise<void> {
        try {
            Launcher.deleteCascadeUrlFile();
        } catch (e) {
            Launcher.trace.info(`cascade.json file was not removed: ${e.message}`);
        }
    }

    /**
     * Writes codepath.json
     */
    public static async writeVSCodeCLIPath(): Promise<void> {
        const programPath = process.argv0;
        const cliPath = await Launcher.getCLIPath();
        const isNewWindow = config.get<boolean>(config.Key.joinInNewWindow) || false;
        const vscodeInfo: VSCodeInfo = { cliPath, programPath, isNewWindow };
        const jsonContent = JSON.stringify(vscodeInfo);
        // Make launcher target path if it doesn't exist since this is used as a part of
        // writeVSCodeCLIPath and readCascadeURL which are invoked prior to installing the launcher.
        if (!await fileAccess.existsAsync((await Launcher.launcherOptions).launcherTargetPath)) {
            mkdirpSync((await Launcher.launcherOptions).launcherTargetPath);
        }
        // write to file
        return fileAccess.writeFileAsync((await Launcher.launcherOptions).codeCLIPathFile, jsonContent);
    }

    private static async getCLIPath(): Promise<string> {
        switch (os.platform()) {
            case OSPlatform.WINDOWS: {
                let codeDir = path.dirname(process.argv0);
                let binDir = path.join(codeDir, 'bin');
                let binFiles = await fileAccess.readdirAsync(binDir);
                let cmdPath = binFiles.find(((value, index, obj) => {
                    // the cli path is different in different flavours of VSCode (ex. code.cmd, code-insiders.cmd, etc)
                    // identify the cli path from the extension rather than the name
                    return path.parse(value).ext === '.cmd';
                }));
                return path.join(binDir, cmdPath);
            }

            case OSPlatform.MACOS: {
                let exePath = process.argv0;
                let appExtension = '.app';

                let appPathEndIndex = exePath.indexOf(appExtension) + appExtension.length;
                let appPath = exePath.substring(0, appPathEndIndex);
                return path.join(appPath, 'Contents', 'Resources', 'app', 'bin', 'code');
            }
            case OSPlatform.LINUX:
            default:
                return process.execPath;
        }
    }

    private static async getLauncherCommand(userInitiated: boolean, installInitiated: boolean = false): Promise<[string, string[]]> {
        switch (os.platform()) {
            case OSPlatform.WINDOWS: {
                const exePath = path.join(Launcher.launcherWinPath, config.get<string>(config.Key.launcherName) + '.exe');
                return [exePath, []];
            }

            case OSPlatform.MACOS: {
                const appPath = path.join(Launcher.launcherOSXPath, config.get<string>(config.Key.launcherName) + '.app');
                const args = [appPath, '--args', '-Register'];

                if (userInitiated) {
                    args.push('-UserInitiated');
                }

                args.push('--extensionRoot', EXTENSION_ROOT_PATH);

                return ['open', args];
               }

            default:
            case OSPlatform.LINUX: {
                 return await this.getLinuxLauncherCommand(userInitiated, installInitiated);
            }
        }
    }

    private static async getLinuxLauncherCommand(userInitiated: boolean, installInitiated: boolean = false): Promise<[string, string[]]> {
        const installScript = path.join(Launcher.launcherLinuxPath, 'install.sh');
        const desktopSourceFile = path.join(Launcher.launcherLinuxPath, 'vsls-launcher.desktop');
        const desktopTargetFile = path.join((await Launcher.launcherOptions).desktopFileTargetPath, 'vsls-launcher.desktop');
        const launcherTargetFile = path.join((await Launcher.launcherOptions).launcherTargetPath, 'vsls-launcher');
        const versionRegex = /X-Version=(.*)/;
        //
        // Don't prompt user to install launcher if already installed,
        // unless user manually wants to reinstall launcher or versions don't match
        // or extension reinstalled (or upgraded).
        //
        // Since the desktop file may still be present but the launcher itself is not
        // (in the event sudo is used to install but not uninstall), check the expected
        // target location as well
        //
        if (!userInitiated && (await fileAccess.existsAsync(desktopTargetFile)) && (await fileAccess.existsAsync(launcherTargetFile))) {
            const currentVersion = fileAccess.readFileSync(desktopSourceFile, 'utf-8').match(versionRegex);
            const installedVersion = fileAccess.readFileSync(desktopTargetFile, 'utf-8').match(versionRegex);

            Launcher.trace.verbose(`Installed Linux launcher is ${installedVersion} and VSIX is ${currentVersion}`);
            // If versions match, don't attempt to reinstall launcher.
            if (currentVersion
                && installedVersion
                && currentVersion[1] === installedVersion[1]
            ) {
                Launcher.trace.info(`Linux launcher ${currentVersion[1]} already installed.`);
                return ['', []];
            }
        }
        // Nothing is installed, so pass back the full install command
        Launcher.trace.info(`Installing Linux launcher using ${installScript}`);
        const shellCommand = ExtensionUtil.getShellCommand();
        // Run quick script to check pre-reqs before firing installer
        const checkResult = child_process.spawnSync(shellCommand, [path.join(Launcher.launcherLinuxPath, 'check-reqs.sh')]);
        if (checkResult.status !== 0) {
            // Non-zero exit code means something went wrong during script execution.
            // 127 can mean missing dependencies, but this is handled in the setup method
            if (checkResult.status) {
                throw Launcher.getErrorForExitCode(checkResult.status);
            }
            throw new Error('check-reqs.sh failed to execute and terminated with signal: ' +
                checkResult.signal +
                (checkResult.stdout ? ' stdout: ' + checkResult.stdout.toString() : '') +
                (checkResult.stderr ? ' stderr: ' + checkResult.stderr.toString() : ''));
        }

        const launcherOptions = await Launcher.launcherOptions;
        return [shellCommand,
            [installScript,
            launcherOptions.codeCLIPathFile,
            launcherOptions.launcherTargetPath,
            launcherOptions.desktopFileTargetPath,
            (launcherOptions.sudoRequired ? 'true' : '')]];
    }

    /*
    * Determines the appropriate options to use for installing the launcher.
    * Particularly applicable to Linux where the target path can vary depending on
    * number of different factors.
    */
    private static async getLauncherOptions() {
        const opts = {
            codeCLIPathFile: path.join(EXTENSION_ROOT_PATH, 'codepath.json'),
            cascadeLaunchUrlFile: path.join(EXTENSION_ROOT_PATH, 'cascade.json'),
            launcherTargetPath: '',
            desktopFileTargetPath: '',
            sudoRequired: false
        };
        // If platform is Linux, check for XDG_DATA_HOME, ~/.local/share to determine correct
        // installation path and whether sudo is required to access it.
        if (os.platform() === OSPlatform.LINUX) {
            const envHome = 'HOME';
            const envXDGDataHome = 'XDG_DATA_HOME';
            const defaultLinuxLauncherTargetPath = path.join(process.env[envHome], '.local', 'share');
            const fallbackLinuxLauncherTargetPath = path.join(process.env[envHome], '.vsliveshare');
            const fallbackLinuxDesktopFileTargetPath = path.join('/', 'usr', 'local', 'share');

            if (process.env[envXDGDataHome]) {
                if (path.normalize(process.env[envXDGDataHome]) === fallbackLinuxDesktopFileTargetPath) {
                    // If XDG_DATA_HOME is /usr/local/share fall back on ~/.vsliveshare for the launcher
                    opts.launcherTargetPath = fallbackLinuxLauncherTargetPath;
                    // If we're not root, sudo will be required to install the desktop file in its fallback location
                    if (process.geteuid() !== 0) {
                        opts.sudoRequired = true;
                    }
                } else {
                    opts.launcherTargetPath = path.join(process.env[envXDGDataHome], 'vsliveshare');
                }
                opts.desktopFileTargetPath = path.join(process.env[envXDGDataHome], 'applications');
            } else {
                // See if ~/.local/share exists. If so, we can use it even if XDG_DATA_HOME is not set.
                if (await fileAccess.existsAsync(defaultLinuxLauncherTargetPath)) {
                    opts.launcherTargetPath = path.join(defaultLinuxLauncherTargetPath, 'vsliveshare');
                    opts.desktopFileTargetPath = path.join(defaultLinuxLauncherTargetPath, 'applications');
                } else {
                    // Fallback to /usr/local/share/applications for the desktop file and ~/.vsliveshare for the launcher
                    opts.launcherTargetPath = fallbackLinuxLauncherTargetPath;
                    opts.desktopFileTargetPath = path.join(fallbackLinuxDesktopFileTargetPath, 'applications');
                    // If we're not root, sudo will be required to install the desktop file in its fallback location
                    if (process.geteuid() !== 0) {
                        opts.sudoRequired = true;
                    }
                }
            }
            opts.codeCLIPathFile = path.join(opts.launcherTargetPath, 'codepath.json');
            opts.cascadeLaunchUrlFile = path.join(opts.launcherTargetPath, 'cascade.json');
        }
        return opts;
    }

    public static async setup(userInitiated: boolean = false, installInitiated: boolean = false) {
        // If running headless, skip launcher installation
        if (await ExtensionUtil.isRunningHeadless()) {
            Launcher.trace.info('Running headless, skipping launcher installation.');
            return;
        }

        const errorMessageTranslocated = 'You are running VS Code outside the Applications folder, so we cannot install support for joining sessions using a browser link. You can still join sessions manually.';
        const errorMessageGeneric = 'Failed to install support for joining sessions using a browser link. You can still join sessions manually.';
        try {
            // Can happen due to app translocation when the app has not been moved from Downloads, and the app path is randomized and read only
            if (await Launcher.isAppTranslocated && (config.get<boolean>(config.Key.showLauncherError) || userInitiated)) {
                // Don't await, or message has to be dismissed before execution continues.
                Launcher.displayLauncherSetupError(errorMessageTranslocated);
            } else {
                await Launcher.writeVSCodeCLIPath();
                const success = await Launcher.run(userInitiated, installInitiated); /* registers the protocol handler */
                if (success) {
                    // Install was successful, so turn on error messaging again
                    // if someone clicked "Never Show this again".
                    await config.save(config.Key.showLauncherError, true);
                    Launcher.trace.info('Launcher installation successful');
                } else {
                    Launcher.trace.info('Launcher installation aborted.');
                }
                if (userInitiated && success) {
                    // Don't await, or message has to be dismissed before execution continues.
                    vscode.window.showInformationMessage('Browser link launcher successfully installed.');
                }
            }
        } catch (e) {
            if (os.platform() === OSPlatform.LINUX && (e.code === 'ERR_NONZERO_EXIT_127' || e === 127)) {
                // If the error is non-zero exit code 127, this indicates a potential missing dependency, so run installer
                Launcher.trace.warning('Could not register the launcher due to missing dependencies.');
                await ExtensionUtil.promptLinuxDependencyInstall('We were unable to install support for joining sessions using a browser link.');
            } else {
                Launcher.trace.error('Could not register the launcher. Error: ' + e);
                if (config.get<boolean>(config.Key.showLauncherError) || userInitiated) {
                    // Don't await, or message has to be dismissed before execution continues.
                    Launcher.displayLauncherSetupError(errorMessageGeneric);
                }
            }
        }
        return;
    }

    private static getErrorForExitCode(exitCode: number): Error {
        const errMessage = 'Launcher installer returned non-zero exit code: ' + exitCode;
        const err = <any> new Error(errMessage);
        err.code = 'ERR_NONZERO_EXIT_' + exitCode;
        Launcher.trace.warning(errMessage);
        return err;
    }

    public static async displayLauncherSetupError(message: string) {
        // setup the launcher
        const neverShowAgain = { title: 'Never show again' };
        const moreInfo = { title: 'Learn more' };

        let option = await vscode.window.showErrorMessage(message, moreInfo, neverShowAgain);

        if (option === moreInfo) {
            ExtensionUtilCore.openBrowser(Launcher.manualJoinUrl);
        }

        if (option === neverShowAgain) {
            await config.save(config.Key.showLauncherError, false);
        }
    }

    public static get isAppTranslocated(): Promise<boolean> {
        return (async () => {
            return os.platform() === OSPlatform.MACOS && (await Launcher.getCLIPath()).startsWith('/private/var');
        })();
    }

    public static readFileContents(filePath: string): Promise<string> {
        return new Promise((resolve, reject) => {
            fileAccess.readFile(filePath, 'utf8', (error, data) => {
                if (error) {
                    reject(error);
                } else {
                    resolve(data);
                }
            });
        });
    }
}

/**
 * Defines the json format of the cascade launcher file containing the launch url.
 * It is written by the launcher, and read by the extension at activation time.
 */
interface CascadeInfo {
    url: string;
}

/**
 * Defines the json format of the vscode information file containg the path of
 * VSCode and the CLI. It is written by the extension and read by the launcher.
 */
interface VSCodeInfo {
    programPath: string;
    cliPath: string;
    isNewWindow: boolean;
}
