
import { fileAccess } from '@vs/vscode-command-framework';
import * as stripJsonComments from 'strip-json-comments';

const cache = new Map<string, any>();

export const loadJSON = (filePath: string, isCache = false) => {
    if (isCache) {
        const data = cache.get(filePath);

        if (data !== undefined) {
            return data;
        }
    }
    
    const jsonWithComments = fileAccess.readFileSync(filePath, 'utf8');
    const json = stripJsonComments(jsonWithComments);
    const result = JSON.parse(json);

    if (isCache) {
        cache.set(filePath, result);
    }

    return result;
};
