'use strict';

import * as sb from '@vside/microsoft-servicebroker';
import {
    IAuthStrategy,
    PackageInfo,
    StackFrame,
    ExtensionContext as ExtensionContextBase,
    LiveShareApi as LiveShareApiBase,
    LiveShareExtensionApi as LiveShareExtensionApiBase } from '@vs/liveshare-api';

import * as config from '../config';
import { TraceSource } from '@vs/vso-logging';
import { IGuestChannelService, Lazy } from 'src/_new_/abstractions/Interfaces';
import { getServiceBrokerForLiveShare } from '../serviceBroker/liveShareServiceBroker';
import getCallingPackage from './getCallingPackage';

interface ExtensionContext {
    channelService?: Lazy<IGuestChannelService>;
}
let privateContext: ExtensionContext;

export class LiveShareExtensionApi extends LiveShareExtensionApiBase {

    public constructor(extensionContext: ExtensionContext, extensionContextBase: ExtensionContextBase) {
        super(extensionContextBase);
        privateContext = extensionContext;
    }

    protected async getCallingPackage(stackFrames: StackFrame[]): Promise<PackageInfo | null> {
        let callingPackage = getCallingPackage('LiveShareExtensionApi.getApi', stackFrames);
        if (!callingPackage) {
            // Check deprecated function name for back-compat.
            callingPackage = getCallingPackage('LiveShareExtensionApi.getApiAsync', stackFrames);
        }

        // Check if the extension or publisher is blocked.
        await config.waitForRemoteUpdateAsync();

        return callingPackage;
    }

    protected createLiveSharApi(callingPackage: PackageInfo, requestedApiVersion: string, trace: TraceSource, authStrategies: IAuthStrategy[] ) {
        return new LiveShareApi(callingPackage, requestedApiVersion, trace, authStrategies);
    }
}

/**
 * Main API that enables other VS Code extensions to access Live Share capabilities.
 *
 * An instance of this class is created by the extension API above.
 */
export class LiveShareApi extends LiveShareApiBase {
    private serviceBroker: sb.IServiceBroker;

    public constructor(
        callingPackage: PackageInfo,
        apiVersion: string,
        trace: TraceSource,
        authStrategies: IAuthStrategy[]
    ) {
        super(callingPackage, apiVersion, trace, authStrategies);
    }

    /**
     * This API is not exposed in the `LiveShare` interface because `IServiceBroker` is not yet
     * public. For now it can be invoked dynamically as an undocumented internal API.
     */
    public async getServiceBroker(): Promise<sb.IServiceBroker | null> {
        if (this.serviceBroker) {
            return this.serviceBroker;
        }

        this.serviceBroker = await getServiceBrokerForLiveShare(privateContext.channelService());

        return this.serviceBroker;
    }
}
