import { vsls } from '@vs/liveshare-core';

import { Disposable } from 'vscode';
import { TraceSource } from '@vs/vso-logging';
import { IAgentSessionContextUpdateListener } from '../abstractions/IAgentSessionContextUpdateListener';
import {
    SessionAction,
    sessionStateTracker,
    ISessionContext,
} from '@vs/liveshare-core';

/**
 * Listens to agent session context updates and wires them through the
 * clients session context state/status chances.
 */
export class AgentSessionContextUpdateListener implements IAgentSessionContextUpdateListener {
    private stateDisposable: Disposable;
    private statusDisposable: Disposable;

    constructor(
        private sessionContextService: vsls.SessionContextService,
        private sessionContext: ISessionContext,
        private trace: TraceSource) {
    }

    public subscribe(): void {
        this.stateDisposable = this.sessionContextService.onSessionStateUpdate((e: vsls.SessionUpdateEventArgs) => {
            const action = (<any>SessionAction)[e.value];
            if (action === undefined) {
                throw new Error(`Unrecognized state transition attempted - "${e.value}".`);
            }
            sessionStateTracker.transition(action);
        });

        this.statusDisposable = this.sessionContextService.onSessionStatusUpdate((e: vsls.SessionUpdateEventArgs) => {
            sessionStateTracker.point('liveshare.' + e.value);
        });
    }

    public dispose(): void {
        if (this.stateDisposable !== undefined) {
            this.stateDisposable.dispose();
        }
        if (this.statusDisposable !== undefined) {
            this.statusDisposable.dispose();
        }
    }
}