import * as configCore from '../../config';

import { Key as ConfigKey } from '../../config';
import {
    featureFlags,
    vsls
} from '@vs/liveshare-core';

export interface IConfigUtil {
    KEYS: typeof ConfigKey;

    get<T>(key: ConfigKey): T | undefined;

    save(key: ConfigKey, value: any, global?: boolean, delaySaveToDisk?: boolean): Thenable<void>;

    featureFlags: vsls.FeatureFlagStore;
}

/**
 * Helper function for working with config settings.
 */
export class ConfigUtil implements IConfigUtil {
    public readonly KEYS = ConfigKey;
    
    public get<T>(key: ConfigKey): T | undefined {
        return configCore.get(key);
    }

    public save(key: ConfigKey, value: any, global: boolean = true, delaySaveToDisk = false): Thenable<void> {
        return configCore.save(key, value, global, delaySaveToDisk);
    }

    public get featureFlags() {
        return featureFlags;
    }
}