import { IDependencies } from '../IDependencies';
import { IAdditionalRootsManager } from '../abstractions/Interfaces';

import {
    vsls,
    ISessionContext,
    workspaceSessionInfoTracker,
    JoinCommandUtilities
} from '@vs/liveshare-core';

export class AdditionalRootsManager implements IAdditionalRootsManager {
    private sessionContext: ISessionContext;
    private fileService: vsls.FileService;

    constructor (dependencies: IDependencies) {
        this.sessionContext = dependencies.sessionContext();
        this.fileService = dependencies.fileService();
    }

    public async init(): Promise<void> {
        JoinCommandUtilities.addAdditionalRootsFromFileServiceToWorkspace(this.fileService, workspaceSessionInfoTracker.workspaceSessionInfo);
    }

    public async dispose(): Promise<void> {}
}
