import { ICommandContext } from '@vs/vscode-command-framework';

import { Key as ConfigKey } from '../../config';

import { dependencies } from '../Dependencies';
import { IConfigUtil } from '../util/ConfigUtil';
import {
    ISessionContext,
    ICommand,
    ICommandDecorator,
    DecoratorHelper
} from '@vs/liveshare-core';

export function firstRunTrackingCommandDecorator(
    commandConfig: ConfigKey) {
    return DecoratorHelper.setupDecorator(
        (command: ICommand<any>) => new FirstRunTrackingCommandDecorator(
            DecoratorHelper.getCoreCommand(command),
            command,
            dependencies.sessionContext(),
            dependencies.configUtil(),
            commandConfig));
}

/**
 * Validation `decorator` that executes validation func prior to running
 * core command.
 */
export class FirstRunTrackingCommandDecorator implements ICommandDecorator {
    constructor(
        private command: ICommand<any>,
        public next: ICommand<any>,
        private sessionContext: ISessionContext,
        private configUtil: IConfigUtil,
        private commandConfig: ConfigKey) {
    }

    public async invoke(options: any, context: ICommandContext): Promise<any> {
        let result: any = undefined;

        // Provide legacy support for tracking first run of share tracking
        this.runLegacySupport();

        // Track the fact that we have or haven't run before
        const hasRunPreviously = !!this.configUtil.get<boolean>(this.commandConfig);
        context.trace.info(`HasRunPreviously: ${context.commandName} -> ${hasRunPreviously}`);
        context.hasRunPreviously = hasRunPreviously;
        if (!hasRunPreviously) {
            this.configUtil.save(this.commandConfig, true);
        }
    
        result = await this.next.invoke(options, context);

        return result;
    }

    private runLegacySupport(): void {
        // Note: The key used to be called `isWelcomePageDisplayed` but this isn't really
        //       descriptive of new usage, but we don't want to loose that we have already
        //       run for some people.
        if (this.commandConfig === ConfigKey.commandFirstRunTrackingShare
            && this.configUtil.get<boolean>(ConfigKey.isWelcomePageDisplayed)) {
                this.configUtil.save(ConfigKey.commandFirstRunTrackingShare, true);
        }
    }
}