import * as vscode from 'vscode';
import * as config from '../../config';
import { InviteLinkJoining, JoinPreReloadCommandOptions } from '../abstractions/IJoinPreReloadCommandOptions';
import {
    vsls,
    PathUtil,
    userAuthStateTracker,
    TelemetryPropertyNames
} from '@vs/liveshare-core';
import {
    ContactManager,
    ContactManagerEvents
} from '@vs/liveshare-contactservice';
import { ICommandContext } from '@vs/vscode-command-framework';

export class JoinCommandUtilities {
    private static vslsLinkRegex = new RegExp(`${config.get<string>(config.Key.scheme)}:\?.*join.*workspaceId=([0-9A-Z-]+)`, 'i');
    private static readonly joinLinkRegex = /([a-z|\-]+\.)+liveshare.*\/join(\/)?\?([0-9a-z]{36})/im;
    private static readonly joinLinkEncodedRegex = /([^\dF][a-z|\-]+\.)+liveshare.*\%2Fjoin(\%2F)?\%3F([0-9a-z]{36})/im;

    public static extractLiveshareWorkspaceId(joinCollaborationLink: string = '') {
        const { linkMatch, linkEncodedMatch, cascadeMatch } = JoinCommandUtilities.getLiveshareLinkMatch(joinCollaborationLink);

        if (linkMatch) {
            return linkMatch[3];
        }

        if (linkEncodedMatch) {
            return linkEncodedMatch[3];
        }

        if (cascadeMatch) {
            return cascadeMatch[1];
        }
    }

    public static extractLiveshareLink(joinCollaborationLink: string = '') {
        const {
            linkMatch,
            linkEncodedMatch,
            cascadeMatch
        } = JoinCommandUtilities.getLiveshareLinkMatch(joinCollaborationLink);

        if (linkMatch) {
            return `https://${linkMatch[0]}`;
        }

        if (linkEncodedMatch) {
            return `https://${decodeURIComponent(linkEncodedMatch[0])}`;
        }

        if (cascadeMatch) {
            return cascadeMatch[0];
        }
    }

    public static async finishInviteLinkJoining(inviteLinkJoining: InviteLinkJoining): Promise<void> {
        if (!inviteLinkJoining) {
            return;
        }
        // transition -> None
        const finishInviteWorkflow = () => ContactManager.fireInviteStatusChanged(
            inviteLinkJoining.targetContactId,
            inviteLinkJoining.fromContactId,
            vsls.InviteContactStatus.None);

        // If no sent message provider it could be related with signed in is in progress
        if (!ContactManager.hasSendMessageProvider) {
            new Promise((resolve) => {
                ContactManager.once(ContactManagerEvents.ProviderCapabilitiesChanged, () => {
                    if (ContactManager.hasSendMessageProvider) {
                        resolve();
                    }
                });
            }).then(finishInviteWorkflow);
        } else {
            await finishInviteWorkflow();
        }
    }

    private static getLiveshareLinkMatch(joinCollaborationLink: string = '') {
        return {
            linkMatch: joinCollaborationLink.match(this.joinLinkRegex),
            linkEncodedMatch: joinCollaborationLink.match(this.joinLinkEncodedRegex),
            cascadeMatch: joinCollaborationLink.match(this.vslsLinkRegex)
        };
    }

    public static isWorkspaceShareable(): boolean {
        let isShareable = false;
        
        // since the util below can throw now, and we already log to telemetry
        // the case when the workspace is not sharable, we ignore the error and
        // just return false.
        try {
            isShareable = !!PathUtil.getPrimaryWorkspaceFileSystemPath();
        } catch (e) {}

        return isShareable;
    }

    public static async invokeJoinCommand(options: JoinPreReloadCommandOptions, context: ICommandContext): Promise<void> {
        const joinPreReloadCommandOptions: JoinPreReloadCommandOptions = {
            newWindow: options.newWindow ? options.newWindow : false,
            link: options.link,
            inviteLinkJoining: options.inviteLinkJoining,
            isAllowAnonymous: options.isAllowAnonymous,
            disableAnonymousPrompt: userAuthStateTracker.isCurrentUserAnonymous()
        };

        (joinPreReloadCommandOptions as any).telemetryProperties = {
            ...(options as any).telemetryProperties,
            [TelemetryPropertyNames.JOIN_INVOKE_COMMAND]: context.commandText
        };
        await vscode.commands.executeCommand<vscode.Uri>(`${config.get<string>(config.Key.commandPrefix)}.joinSession`, joinPreReloadCommandOptions);
    }
}
