import * as rpc from 'vscode-jsonrpc';
import * as vscode from 'vscode';
import * as net from 'net';
import * as uuid from 'uuid';
import { traceSource } from '@vs/vscode-command-framework';
import { TraceSource } from '@vs/vso-logging';
import { IRPCClient } from '../abstractions/IRPCClient';
import { vsls } from '@vs/liveshare-core';

import stdfork = require('./stdFork');
import { DebugProtocol } from 'vscode-debugprotocol';
import { Lazy } from '../_new_/abstractions/Interfaces';
import { RunInTerminalHandler, IHostAdapterService } from './IHostAdapterService';
import { getPipePath } from '../utils/getPipePath';

import {
    IClientAccessCheck, 
    GuestIdSessionContext,
    RestrictedOperation,
    WellKnownRestrictedOperations,
} from '@vs/liveshare-core';

export const sourceEventNotificationType: rpc.NotificationType<vsls.SourceEventArgs, any> = new rpc.NotificationType('sourceEvent.event');

export class HostAdapterService implements IHostAdapterService {
    private static readonly debugContinueOperation: RestrictedOperation = { name: WellKnownRestrictedOperations.DebugContinue };
    private static readonly debugSetVariableOperation: RestrictedOperation = { name: WellKnownRestrictedOperations.DebugSetVariable };
    private static readonly debugEvaluateOperation: RestrictedOperation = { name: WellKnownRestrictedOperations.DebugEvaluate };

    private server: net.Server;
    private rpcConnections: Array<rpc.MessageConnection> = [];
    private readonly trace: TraceSource;

    public readonly pipeName: string;
    public runInTerminal: RunInTerminalHandler = null;

    constructor(private client: IRPCClient, clientAccessCheck: Lazy<IClientAccessCheck>) {
        this.trace = traceSource.withName(vsls.TraceSources.DebugRpcHost);
        this.pipeName = uuid().replace(/-/g, '');

        let self = this;
        let logger: rpc.Logger;
        logger = this;

        this.server = net.createServer(function (socket) {
            let pipeConnection = rpc.createMessageConnection(socket, socket, logger);
            self.rpcConnections.push(pipeConnection);

            // Support for 'sendRequest' request
            const invokeType = new rpc.RequestType<any[], any, void, void>('VSCodeAdapterService.sendRequest');
            pipeConnection.onRequest(invokeType, async (values) => {
                const command = <string>values[0];
                values.splice(0, 1);
                let response = await client.sendRequest<any>(self.trace, command, null, null, ...values);
                return response;
            });

            // Support for 'sendNotification' request
            const sendNotificationType = new rpc.NotificationType<any[], any>('VSCodeAdapterService.sendNotification');
            pipeConnection.onNotification(sendNotificationType, async (values) => {
                const eventName = <string>values[0];
                await client.sendNotification(self.trace, eventName, values[1]);
            });

            // Support for register service request
            const registerServiceType = new rpc.RequestType<any[], void, void, void>('VSCodeAdapterService.registerService');
            pipeConnection.onRequest(registerServiceType, async (values) => {
                // Register the Service on our workspace
                const serviceName = <string>values[0];
                await client.sendRequest(self.trace, 'workspace.registerServices', null, null, [serviceName], 'Add');

                const requestMethods = <string[]>values[1];
                for (let methodName of requestMethods) {
                    client.addRequestMethodWithContext(methodName, async (...params: any[]) => {

                        // Get context from the second-to-last parameter and remove it from the parameters.
                        const context: GuestIdSessionContext = params[params.length - 2];
                        params.splice(params.length - 2, 1);

                        // Check if the operation is allowed.
                        const restrictedOperation = HostAdapterService.getRestrictedOperation(methodName, params);
                        await clientAccessCheck().verifyCanPerformOperation(context, restrictedOperation);

                        // Forward the request to the pipe connection.
                        let response = await pipeConnection.sendRequest(methodName, params);
                        return response;
                    });
                }
            });

             // Support for unregister service request
            const unregisterServiceType = new rpc.RequestType<any[], void, void, void>('VSCodeAdapterService.unregisterService');
            pipeConnection.onRequest(unregisterServiceType, async (values) => {
                 // Unregister the Service on our workspace
                 // Param 0: serviceName
                 // Param 1: list of methods to unregister
                 const serviceName = <string>values[0];
                 await client.sendRequest(self.trace, 'workspace.registerServices', null, null, [serviceName], 'Remove');

                 const requestMethods = <string[]>values[1];
                 for (let methodName of requestMethods) {
                     client.removeRequestMethod(methodName);
                 }
             });

            // Support for register notifications
            const registerNotificationsType = new rpc.RequestType<any[], number[], void, void>('VSCodeAdapterService.registerNotifications');
            pipeConnection.onRequest(registerNotificationsType, async (values) => {
                let cookies = [];
                for (let eventName of values) {
                    const cookie = client.addNotificationHandler(eventName, async (...params: any[]) => {
                        await pipeConnection.sendNotification(eventName, ...params);
                    });
                    cookies.push(cookie);
                }

                return cookies;
            });

            // Support for unregister notifications
            const unregisterNotificationsType = new rpc.RequestType<any[], void, void, void>('VSCodeAdapterService.unregisterNotifications');
            pipeConnection.onRequest(unregisterNotificationsType, async (values) => {
                for (let entry of values) {
                    client.removeNotificationHandler(entry.name, entry.cookie);
                }
            });

            // Support for request received service request
            const requestReceivedType = new rpc.RequestType<any[], any, void, void>('VSCodeAdapterService.requestReceived');
            pipeConnection.onRequest(requestReceivedType, async (values) => {
                const command = <string>values[0];
                const requestArgs = values[1];

                if (command === 'runInTerminal' && self.runInTerminal) {
                    const result = await self.runInTerminal(<DebugProtocol.RunInTerminalRequestArguments> requestArgs);
                    if (result && result.response) {
                        return {
                            handled: true,
                            response: result.response
                        };
                    } else {
                        return {
                            arguments: result && result.args ? result.args : requestArgs
                        };
                    }
                }

                return { handled: false };
           });

            // Support for 'enterRunMode' request
            const enterRunRequestType = new rpc.RequestType<string[], void, void, void>('VSCodeAdapterService.enterRunMode');
            pipeConnection.onRequest(enterRunRequestType, async (values) => {
                let reason = values[0];

                console.log(`HostAdapterService::enterRunMode:${reason}`);
                if (reason === 'go') {
                    await vscode.commands.executeCommand('workbench.action.debug.continue');
                } else if (reason === 'step') {
                    await vscode.commands.executeCommand('workbench.action.debug.stepOver');
                }
            });

            const nodeForkType = new rpc.RequestType<string, any, void, void>('VSCodeAdapterService.nodeFork');
            let stdforkHandler = (values: any): Promise<any> => new Promise((resolve, reject) => {
                stdfork.fork(self.trace, values[0], (err, child, processInfo) => {
                    if (err) {
                        reject(err);
                    } else {
                        resolve(processInfo);
                    }
                });
            });
            pipeConnection.onRequest(nodeForkType, stdforkHandler);

            pipeConnection.onClose((e) => {
                let index = self.rpcConnections.indexOf(pipeConnection);
                if (index > -1) {
                    self.rpcConnections.splice(index, 1);
                }
            });

            pipeConnection.listen();
        });

        let launchCallback = (error: any) => {
        };

        //this.server.on("error", this.recoverServer.bind(this));
        this.server.listen(getPipePath(this.pipeName), launchCallback);
    }

    public dispose(): void {
        this.server.close();
    }

    private static getRestrictedOperation(methodName: string, params: any[]): RestrictedOperation {
        if (HostAdapterService.isContinueRequest(methodName)) {
            return HostAdapterService.debugContinueOperation;
        }

        if (HostAdapterService.isSetVariableRequest(methodName, params)) {
            return HostAdapterService.debugSetVariableOperation;
        }

        if (HostAdapterService.isEvaluateRequest(methodName, params)) {
            return HostAdapterService.debugEvaluateOperation;
        }

        return null;
    }

    private static isContinueRequest(methodName: string): boolean {
        return methodName && typeof methodName === 'string' && methodName.endsWith('.continue');
    }

    private static isSetVariableRequest(methodName: string, params: any[]): boolean {
        return methodName && typeof methodName === 'string' && methodName.endsWith('.handleProtocolRequest') &&
               params && Array.isArray(params) && params.length > 0 && params[0] === 'setVariable';
    }

    private static isEvaluateRequest(methodName: string, params: any[]): boolean {
        return methodName && typeof methodName === 'string' && methodName.endsWith('.handleProtocolRequest') &&
               params && Array.isArray(params) && params.length > 1 && params[0] === 'evaluate'
               && params[1] && params[1].context !== 'hover';
    }

    // Implement Logger
    public error(message: string): void { }
    public warn(message: string): void { }
    public info(message: string): void { }
    public log(message: string): void { }
}