import * as vscode from 'vscode';

import { INotificationUtil } from '../abstractions/INotificationUtil';
import { ExtensionUtil } from '@vs/liveshare-core';
import * as config from '../../config';

/**
 * Helper functions for working with VS Code Notifications/toasts.
 */
export class NotificationUtil implements INotificationUtil {
    private static singleton: NotificationUtil;

    public static get Instance(): NotificationUtil {
        if (!NotificationUtil.singleton) {
            NotificationUtil.singleton = new NotificationUtil();
        }
        return NotificationUtil.singleton;
    }

    public showInformationMessage(message: string, isVerbose: boolean, ...items: string[]): Thenable<string | undefined>;
    public showInformationMessage<T extends vscode.MessageItem>(message: string, isVerbose: boolean, options: vscode.MessageOptions, ...items: T[]): Thenable<T | undefined>;
    public showInformationMessage(message: string, isVerbose: boolean, ...items: any[]): any {
        if (!isVerbose || config.get<boolean>(config.Key.showVerboseNotifications)) {
            return vscode.window.showInformationMessage(message, ...items);
        }
    }

    public showErrorInformationMessage(message: string, ...items: string[]): Thenable<string | undefined>;
    public showErrorInformationMessage<T extends vscode.MessageItem>(message: string, options: vscode.MessageOptions, ...items: T[]): Thenable<T | undefined>;
    public showErrorInformationMessage(message: string, ...items: any[]): any {
        return vscode.window.showErrorMessage(message, ...items);
    }

    public showErrorMessage(message: string, ...items: string[]): Thenable<string | undefined>;
    public showErrorMessage<T extends vscode.MessageItem>(message: string, options: vscode.MessageOptions, ...items: T[]): Thenable<T | undefined>;
    public showErrorMessage(message: string, ...items: any[]): any {
        return ExtensionUtil.showErrorAsync(message, ...items);
    }

    public showWarningMessage(message: string): Thenable<void> {
        return vscode.window.showWarningMessage(message).then(() => {});
    }

    public showInputBox(options?: vscode.InputBoxOptions, token?: vscode.CancellationToken): Thenable<string | undefined> {
        return vscode.window.showInputBox(options, token);
    }

    public showQuickPick<T extends vscode.QuickPickItem>(items: T[] | Thenable<T[]>, options?: vscode.QuickPickOptions, token?: vscode.CancellationToken): Thenable<T | undefined>;
    public showQuickPick(items: string[], options?: vscode.QuickPickOptions, token?: vscode.CancellationToken): Thenable<string | undefined> {
        return vscode.window.showQuickPick(items, options, token);
    }

    public withProgress<R>(options: vscode.ProgressOptions, task: (progress: vscode.Progress<{ message?: string; }>, token: vscode.CancellationToken) => Thenable<R>, token?: vscode.CancellationToken): Thenable<R> {
        // TODO: playing with the signatures here due to version difference
        return vscode.window.withProgress(options, task as (progress: vscode.Progress<{ message?: string; }>) => Thenable<R>);
    }
        
    public async showOpenDialog(options: vscode.OpenDialogOptions): Promise<vscode.Uri[] | undefined> {
        return await vscode.window.showOpenDialog(options);
    }
}

const Instance = NotificationUtil.Instance;
export { Instance };
