import { CancellationToken } from 'vscode';
import { Agent } from './agent';
import * as os from 'os';
import {
    vsls,
    sessionStateTracker,
    SessionAction,
    AuthenticationProviderBase,
    AuthenticationOptions,
    TelemetryPropertyNames,
    Lazy,
    lazyLoad,
    ExtensionUtil
} from '@vs/liveshare-core';
import { ICommandContext, traceSource } from '@vs/vscode-command-framework';
import { CancellationError } from '@vs/vso-rpc';

import { OSPlatform } from '../../osPlatform';
import { AuthenticationFindCodeUtilLinux } from '../../_new_/authentication/AuthenticationFindCodeUtilLinux';
import { AuthenticationFindCodeUtilMacWin } from '../../_new_/authentication/AuthenticationFindCodeUtilMacWin';
import { IAuthenticationFindCodeUtil } from '../../_new_/abstractions/IAuthenticationFindCodeUtil';

import { NotificationUtil } from '../../_new_/util/NotificationUtil';
import { dependencies } from '../../_new_/Dependencies';

import * as uuid4 from 'uuid/v4';

/**
 * Provider which tracks whether the user is currently logged in or not.
 */
export class AuthenticationProvider extends AuthenticationProviderBase {
    private currentLoginUri: string;

    private authenticationFindCodeUtil:  Lazy<IAuthenticationFindCodeUtil> = lazyLoad(
        () => os.platform() === OSPlatform.LINUX ?
        new AuthenticationFindCodeUtilLinux(NotificationUtil.Instance, traceSource) : 
        new AuthenticationFindCodeUtilMacWin(dependencies.authService()));

    constructor(vslsAuthService: vsls.AuthenticationService) {
        super(vslsAuthService); 
    }

    public async attemptLoginFlowCoreBrowser(options: AuthenticationOptions, context: ICommandContext): Promise<boolean> {
        const { cancellationTokenSource } = context;
        const cancellationToken = cancellationTokenSource && cancellationTokenSource.token;

        if (cancellationToken && cancellationToken.isCancellationRequested) {
            context.telemetryEvent.addProperty(TelemetryPropertyNames.AUTH_CANCEL_BROWSER_CANCEL, true);
            throw new CancellationError();
        }

        const instanceId = uuid4();
        const loginUri = await this.getLoginUri(instanceId, cancellationToken);

        // Open browser to allow user to go through oAuth flow.
        ExtensionUtil.openBrowser(loginUri);

        sessionStateTracker.transition(SessionAction.AwaitExternalSignIn);
        sessionStateTracker.point(TelemetryPropertyNames.EXTERNAL_SIGNIN_STARTING);
        
        // Pause execution whilst we wait for external code to return.
        const userCode = await this.authenticationFindCodeUtil().findLoginCode(instanceId, cancellationToken);
        if (!userCode || (cancellationToken && cancellationToken.isCancellationRequested)) {
            sessionStateTracker.transition(SessionAction.SignOut);
            context.telemetryEvent.addProperty(TelemetryPropertyNames.AUTH_CANCEL_WAIT_FOR_CODE, true);
            throw new CancellationError();
        }

        sessionStateTracker.point(TelemetryPropertyNames.EXTERNAL_SIGNIN_COMPLETE);
        sessionStateTracker.transition(SessionAction.AttemptSignIn);

        // Attempt to login with the returned user code.
        return await this.attemptLogin(userCode, options, cancellationToken);
    }
    
    protected async waitForAuthenticateService(): Promise<void> {
        await Agent.waitForAgentStart();
    }

    private async getLoginUri(instanceId: string, cancellationToken?: CancellationToken) {
        const baseLoginUri = await this.getCurrentLoginUri(cancellationToken);
        return `${baseLoginUri}?extensionId=${instanceId}`;
    }

    private async getCurrentLoginUri(cancellationToken?: CancellationToken): Promise<string> {
        return this.currentLoginUri || (this.currentLoginUri = await (<vsls.AuthenticationService>this.authService).getLoginUriAsync());
    }
}