import * as url from 'url';
import * as vscode from 'vscode';

class MementoConfig {
    private static singleton: MementoConfig;
    private globalState: vscode.Memento | undefined;

    public static get Instance(): MementoConfig {
        if (!MementoConfig.singleton) {
            MementoConfig.singleton = new MementoConfig();
        }
        return MementoConfig.singleton;
    }

    public async initAsync(context: vscode.ExtensionContext): Promise<void> {
        this.globalState = context.globalState;
    }

    public get<T>(key: string): T | undefined {
        return this.globalState ? this.globalState.get<T>(key) : undefined;
    }

    public async save(key: string, value: any): Promise<void> {
        if (!this.globalState) {
            throw new Error('Not initialized.');
        }
        this.globalState.update(key, value);
    }

    public getUri(keyString: string): url.Url | undefined {
        let value = this.get<string>(keyString);
        if (!value) {
            return undefined;
        }

        try {
            return url.parse(value);
        } catch (e) {
            return undefined;
        }
    }
}

const mementoConfigInstance = MementoConfig.Instance;
export { mementoConfigInstance as MementoConfig };