import * as path from 'path';
import * as jsonc from 'jsonc-parser';
import * as vscode from 'vscode';

import { traceSource, fileAccess } from '@vs/vscode-command-framework';
import { TraceSource } from '@vs/vso-logging';

import * as config from '../config';
import { Telemetry } from '@vs/vso-telemetry';
import { IRPCClient } from '../abstractions/IRPCClient';

import {
    vsls,
    Lazy,
    IClientAccessCheck,
    PathUtil,
    RestrictedOperation,
    WellKnownRestrictedOperations,
    TelemetryEventNames,
    TelemetryPropertyNames
} from '@vs/liveshare-core';

export class ShareDebugManagerBase  {
    public static readonly debugHostAdapterName = 'Microsoft.VisualStudio.LiveShare.Debugger.VSCodeHostAdapter';
    private static readonly getCurrentDebugSessionsMethodName = 'getCurrentDebugSessions';
    private static readonly debugSessionChangedEventName = 'debugSessionChanged';
    private static readonly vscodeLaunchPath = '.vscode/launch.json';
    private static readonly launchDebugOperation: RestrictedOperation = {
        name: WellKnownRestrictedOperations.LaunchDebug,
        isEnabled: () => config.get<boolean>(config.Key.allowGuestDebugControl) || { errorCode: vsls.ErrorCodes.RemoteLaunchNotEnabled, errorMessage: 'Remote launch not enabled.'},
    };

    protected activeDebugSessions: Array<vsls.DebugSession> = [];
    protected readonly trace: TraceSource;
    public isSharing: boolean;
    private readonly isSharingChanged = new vscode.EventEmitter<boolean>();

    constructor(
        private rpcClient: IRPCClient,
        private fileService: vsls.FileService,
        private clientAccessCheck: Lazy<IClientAccessCheck>) {

        // Create our trace source
        this.trace = traceSource.withName(vsls.TraceSources.DebugRpcHost);
        this.fileService.onFilesChanged(this.onFilesChanged, this);
    }

    public get onDidChangeIsSharing(): vscode.Event<boolean> {
        return this.isSharingChanged.event;
    }

    public async setShareState(isSharing: boolean): Promise<void> {
        if (isSharing) {
            // register myself as the IDebuggerHostService contract
            await this.registerDebuggerHostService(true);
            // handle 'getCurrentDebugSessions' method
            this.rpcClient.addRequestMethod(
                ShareDebugManagerBase.getDebuggerHostServiceAndName(ShareDebugManagerBase.getCurrentDebugSessionsMethodName),
                (...params: any[]) => {
                    return this.activeDebugSessions;
            });

            // handle 'launchDebugSession' method
            this.rpcClient.addRequestMethodWithContext(
                ShareDebugManagerBase.getDebuggerHostServiceAndName('launchDebugSession'),
                async (debugConfiguration: any, context, token: vscode.CancellationToken) => {

                    // Verify if not in read-only mode and has setting allowing this
                    await this.clientAccessCheck().verifyCanPerformOperation(context, ShareDebugManagerBase.launchDebugOperation);

                    // When being used against matching extension versions, we
                    // may be provided with a workspace to launch against. This
                    // is critical because a debug configuration is actually resolved
                    // against the workspace. Without it, you'll start the correct
                    // debug config, but the wrong paths (e.g. won't find binaries).
                    // This leverages an extra property smuggled into the debug
                    // config from the client. Default to the primary one if it's
                    // not been provided.
                    const workspaceFolderIndex = debugConfiguration.__workspaceIndex || 0;
                    let folderToDebug = vscode.workspace.workspaceFolders ?
                        vscode.workspace.workspaceFolders[workspaceFolderIndex] :
                        undefined;
                    this.trace.info(`Starting Debugging for ${debugConfiguration.name}, in workspace ${workspaceFolderIndex}`);

                    const result = await vscode.debug.startDebugging(folderToDebug, debugConfiguration);

                    if (!result) {
                        throw new Error(`Failed to launch debug configuration:${debugConfiguration.name}, in workpace ${folderToDebug.name}`);
                    }

                    // When we successfully started debugging, report the workspace
                    // we started it for (index), and the total count
                    //let folderCount = vscode.workspace.workspaceFolders ? vscode.workspace.workspaceFolders.length : 0;
                    Telemetry.sendTelemetryEvent(TelemetryEventNames.GUEST_INITIATED_DEBUGGING,
                        null, // No Properties
                        { // Measures
                            [TelemetryPropertyNames.DEBUGGING_STARTED_WORKSPACE_FOLDER]: workspaceFolderIndex,
                            [TelemetryPropertyNames.DEBUGGING_STARTED_WORKSPACE_FOLDER_COUNT]: (vscode.workspace.workspaceFolders ? vscode.workspace.workspaceFolders.length : 0)
                        }
                    );
            });

            // handle 'getLaunchConfigurations' method
            this.rpcClient.addRequestMethod(
                ShareDebugManagerBase.getDebuggerHostServiceAndName('getLaunchConfigurations'),
                async (token: vscode.CancellationToken) => {
                    return await ShareDebugManagerBase.getLaunchConfigurationsContent();
            });

        } else {
            this.rpcClient.removeRequestMethod(ShareDebugManagerBase.getDebuggerHostServiceAndName(ShareDebugManagerBase.getCurrentDebugSessionsMethodName));
            this.rpcClient.removeRequestMethod(ShareDebugManagerBase.getDebuggerHostServiceAndName('launchDebugSession'));
            this.rpcClient.removeRequestMethod(ShareDebugManagerBase.getDebuggerHostServiceAndName('getLaunchConfigurations'));

            // un-register myself as the IDebuggerHostService contract
            await this.registerDebuggerHostService(false);
        }

        this.isSharing = isSharing;
        this.isSharingChanged.fire(isSharing);
    }

    public async addDebugSession(debugSession: vsls.DebugSession, notify?: boolean): Promise<void> {
        this.activeDebugSessions.push(debugSession);
        if (notify && this.isSharing) {
            await this.notifySharedDebugSession(debugSession, true);
        }
    }

    public async removeDebugSession(sessionId: string): Promise<void> {
        const index = this.activeDebugSessions.findIndex( (d) => d.sessionId === sessionId);
        if (index >= 0) {
            const debugSession = this.activeDebugSessions[index];
            this.activeDebugSessions.splice(index, 1);

            if (this.isSharing) {
                await this.notifySharedDebugSession(debugSession, false);
            }
        }
    }

    private async registerDebuggerHostService(add: boolean): Promise<void> {
        // register myself as the IDebuggerHostService contract
        await this.rpcClient.sendRequest(this.trace, 'workspace.registerServices', null, null, [vsls.DebuggerHostService.name], add ? 'Add' : 'Remove');
    }

    protected async notifySharedDebugSession(debugSessionInfo: vsls.DebugSession, isAdded: boolean): Promise<void> {
        this.trace.info(`notifySharedDebugSession id:${debugSessionInfo.sessionId} isAdded:${isAdded}`);
        const debugSessionEventArgs = {
            changeType: isAdded ? vsls.DebugSessionChangeType.Add : vsls.DebugSessionChangeType.Remove,
            debugSession: debugSessionInfo
        };
        await this.rpcClient.sendNotification(
            this.trace,
            ShareDebugManagerBase.getDebuggerHostServiceAndName(ShareDebugManagerBase.debugSessionChangedEventName),
            debugSessionEventArgs);
    }

    private async onFilesChanged(e: vsls.FilesChangedEventArgs): Promise<void> {
        const changePath = PathUtil.getRelativePathFromPrefixedPath(e.changes[0].fullPath);
        if (changePath === '/' + ShareDebugManagerBase.vscodeLaunchPath) {
            const launchConfigurationsContent = await ShareDebugManagerBase.getLaunchConfigurationsContent();
            this.rpcClient.sendNotification(
                this.trace,
                ShareDebugManagerBase.getDebuggerHostServiceAndName('launchConfigurationsChanged'),
                {
                    launchConfigurations: launchConfigurationsContent
                });
        }
    }

    public static fillDebugSession(
        vslsDebugSession: vsls.DebugSession,
        debugSession: vscode.DebugSession,
        capabilities: any,
        configurationProperties: {[key: string]: any}): void {
    
        vslsDebugSession.sessionId = debugSession.id,
        vslsDebugSession.name = debugSession.name,
        vslsDebugSession.processId = undefined,
        vslsDebugSession.capabilities = capabilities,
        vslsDebugSession.configurationProperties = configurationProperties;
    }

    private static getDebuggerHostServiceAndName(name: string): string {
        return vsls.DebuggerHostService.name + '.' + name;
    }

    private static async getLaunchConfigurationsContent(): Promise<string> {
        if (!vscode.workspace.workspaceFolders) {
            return undefined;
        }
        const launchJsonsByRoot = await Promise.all(vscode.workspace.workspaceFolders.map(async (folder) => {
            const launchJsonPath = path.join(folder.uri.fsPath, ShareDebugManagerBase.vscodeLaunchPath);
            if (!await fileAccess.existsAsync(launchJsonPath)) {
                return null;
            }

            try {
                const content = fileAccess.readFileSync(launchJsonPath, 'utf8');
                return {
                    root: folder.index.toString(),
                    content: jsonc.parse(content),
                };
            } catch {
                return null;
            }
        }));

        let configuration: any = null;
        if (launchJsonsByRoot[0] && launchJsonsByRoot[0].content) {
            configuration = launchJsonsByRoot[0].content;
        }

        launchJsonsByRoot.shift();

        if (!launchJsonsByRoot.length) {
            return configuration ? JSON.stringify(configuration) : null;
        }

        let rootsWithContent = 0;
        const configurationsByRoot: { [key: string]: any} = {};
        launchJsonsByRoot.forEach((item) => {
            if (!item || !item.content) {
                return;
            }

            rootsWithContent += 1;
            configurationsByRoot[item.root] =  item.content;
        });

        if (rootsWithContent === 0) {
            return null;
        }

        if (!configuration) {
            configuration = {};
        }

        configuration.configurationsByRoot = configurationsByRoot;

        return JSON.stringify(configuration);
    }
}