import * as vscode from 'vscode';
import * as config  from '../config';
import { ViewItem } from '@vs/liveshare-api';
import {
    CommandId,
    TreeViewItem,
    Settings
} from '@vs/liveshare-core';

interface LabelAndLink {
    label: string;
    link: string;
    location: string;
}

export interface TreeViewItemOptions {
    type: ViewItem;
    label: string;
    tooltip?: string;
    command?: vscode.Command;
    collapsibleState?: vscode.TreeItemCollapsibleState;
    contextValue?: string;
    iconPath?: string | vscode.Uri | { light: string | vscode.Uri; dark: string | vscode.Uri };
}

export async function getLabelAndLinkTreeViewItems (location: string): Promise<TreeViewItem[]> {
    const labelAndLinks =  config.get<LabelAndLink[]>(config.Key.remoteLabelAndLinks) || [];
    const treeViewItems: TreeViewItem[] = [];
    // Only show these to users that have at least 5 sessions
    if ((Settings.isInsidersFeatureSet || Settings.isInternalFeatureSet) && config.get<number>(config.Key.sessionCount) >= 5) { 
        labelAndLinks.filter(x => x.location === location).forEach((x) => {
            treeViewItems.push(
                new TreeViewItem({
                    type: ViewItem.Other,
                    collapsibleState: vscode.TreeItemCollapsibleState.None,
                    label: x.label,
                    command: {
                        title: x.label,
                        command: CommandId.openLink,
                        arguments: [x.link]
                    }
                })
            );
        
        }); 
    }
    return treeViewItems;
}