import * as vscode from 'vscode';
import * as semver from 'semver';
import * as cached from 'vscode-cached-file-search-provider';

import * as config from '../../config';
import { ExtensionUtil } from '@vs/liveshare-core';

import { IDependencies } from '../IDependencies';
import { ISearchProviderManager } from '../abstractions/Interfaces';
import { SearchProvider } from '@vs/liveshare-core';

export class SearchProviderManager implements ISearchProviderManager {

    constructor (private dependencies: IDependencies) {}

    public async init(): Promise<void> {
        if (semver.gte(semver.coerce(vscode.version), '1.26.0') &&
            vscode.workspace.registerTextSearchProvider) {
                const provider = new SearchProvider(this.dependencies);
                ExtensionUtil.context.subscriptions.push(vscode.workspace.registerTextSearchProvider(
                    config.get<string>(config.Key.authority), provider));
                if (semver.gte(semver.coerce(vscode.version), '1.30.0') && vscode.workspace.registerFileSearchProvider) {
                    ExtensionUtil.context.subscriptions.push(vscode.workspace.registerFileSearchProvider(
                        config.get<string>(config.Key.authority), new cached.CachedSearchProvider(provider)
                    ));
                } else if (vscode.workspace.registerFileIndexProvider) {
                    ExtensionUtil.context.subscriptions.push(vscode.workspace.registerFileIndexProvider(
                        config.get<string>(config.Key.authority), provider));
                }
        }
    }

    public async dispose(): Promise<void> {}
}
