import { fileAccess, traceSource } from '@vs/vscode-command-framework';
import { ExtensionUtil } from '@vs/liveshare-core';
import * as path from 'path';
import * as tmp from 'tmp';
import * as util from './util';

import * as extractZip from 'extract-zip';
import * as tar from 'tar';
import * as crypto from 'crypto';
import * as glob from 'glob';
import * as os from 'os';
import * as vscode from 'vscode';

interface IDownloadOptions {
    followRedirect?: boolean;
    useElectronNet?: boolean;
}

let download = function(url: string, options?: IDownloadOptions): Promise<Buffer> {
    // The 'npm-conf' package, a transitive dependency of the 'download' package,
    // changes `process.env.HOME`, which can cause problems for other extensions
    // in the same host process. There's no way to avoid it while still using the
    // 'download' package. So as a workaround this wrapper restores the env variable
    // after importing the package.
    const homeEnv = process.env.HOME;

    // Overwite the download variable so any future invocations skip this wrapper.
    download = require('download');

    if (homeEnv) process.env.HOME = homeEnv;
    else delete process.env.HOME;

    return download(url, options);
};

export interface Package {
    code: string;
    description: string;
    url: string;
    platforms: string[];
    architectures: string[];
    tmpFile: tmp.SynchrounousResult;
    checksum: string;
    fileTotal: number;

    // Path of the final resting/install place of the files.
    installPath?: string;

    // Path inside the zip file to treat as the root.
    packageRootPath: string;

    // Path to use to test if the package has already been installed
    installTestPath?: string;

    // Path where we want to pack into, if left undefined will use `installPath`
    unpackPath?: string;

    // Path that should when cleanup up after a bad install, if not defined
    // and `unpackPath != installPath` it will use the `unpackPath` path,
    // otherwise no delete will be performed
    retryDeletePath?: string;
}

export interface PackageStats {
    [key: string]: {
        didDownload?: boolean;
        checksumPass?: boolean;
        vscodeDownload?: boolean;
        totalBaseFilesPreUnpack?: number;
        totalBaseFilesPostUnpack?: number;
        totalBaseFilesPreMove?: number;
        totalBaseFilesPostMove?: number;
        totalFilesExtracted?: number;
        totalFileMovedOffset?: number;
    };
}

export interface Status {
    setMessage: (text: string) => void;
}

export class PackageError extends Error {
    // Do not put PII (personally identifiable information) in the 'message' field as it will be logged to telemetry
    constructor(public message: string,
                public pkg: Package = null,
                public innerError: any = null) {
        super(message);
    }
}

export class PackageManager {
    private allPackages: Package[];
    private packageStats: PackageStats = {};
    private tempPath: string = 'temp';

    get stats(): PackageStats {
        return this.packageStats;
    }

    public constructor(
        private platform: string,
        private architecture: string,
        private packageJSON: any) {

        if (this.packageJSON.runtimeDependencies) {
            this.allPackages = <Package[]>this.packageJSON.runtimeDependencies;
        } else {
            throw(new PackageError('Package manifest does not exist.'));
        }

        // Ensure our temp files get cleaned up in case of error.
        tmp.setGracefulCleanup();
    }

    public static getLiveSharePackages(): Package[] {
        const packageJSON = vscode.extensions.getExtension('ms-vsliveshare.vsliveshare').packageJSON;
        const platform = os.platform();
        const arch = os.arch();
        if (packageJSON.runtimeDependencies) {
            const allPackages = <Package[]>packageJSON.runtimeDependencies;
            return allPackages.filter(pkg => {
                if (pkg.architectures && pkg.architectures.indexOf(arch) === -1) {
                    return false;
                }

                if (pkg.platforms && pkg.platforms.indexOf(platform) === -1) {
                    return false;
                }

                return true;
            });
        } else {
            throw(new PackageError('Package manifest does not exist.'));
        }
    }

    public static getDotnetInstallPath() {
        const packages = PackageManager.getLiveSharePackages();

        const dotNetCorePackage = packages.find(pkg => pkg.code.startsWith('NetCore'));
        if (!dotNetCorePackage) {
            throw(new PackageError('DotNetCore package does not exist!'));
        }

        return path.join(ExtensionUtil.getGlobalStoragePath(), dotNetCorePackage.installPath);
    }

    private getPackages(): Package[] {
        let list = this.allPackages;

        return list.filter(pkg => {
            if (pkg.architectures && pkg.architectures.indexOf(this.architecture) === -1) {
                return false;
            }

            if (pkg.platforms && pkg.platforms.indexOf(this.platform) === -1) {
                return false;
            }

            return true;
        });
    }

    public async downloadPackagesAsync(status: Status): Promise<boolean> {
        let downloaded = false;
        const packages = this.getPackages();

        for (const pkg of packages) {
            this.stats[pkg.code] = {};
            if (await this.maybeDownloadPackageAsync(pkg, status)) {
                downloaded = true;
            }
        }

        return downloaded;
    }

    public async installPackagesAsync(status: Status): Promise<boolean> {
        let installed = false;
        const packages = this.getPackages();

        for (const pkg of packages) {
            if (await this.installPackageAsync(pkg, status)) {
                installed = true;
            }
        }

        return installed;
    }

    public static getBaseInstallPath(pkg: Package): string {
        let basePath = ExtensionUtil.getGlobalStoragePath();
        if (pkg.installPath) {
            basePath = path.join(basePath, pkg.installPath);
        }

        return basePath;
    }

    public static getBaseUnpackPath(basePath: string, pkg: Package): string {
        if (pkg.unpackPath) {
            basePath = path.join(basePath, pkg.unpackPath);
        }

        return basePath;
    }

    public static async ensureCleanInstallPath(installPath: string) {
        if (installPath && await fileAccess.pathExists(installPath)) {
            await fileAccess.remove(installPath);

            traceSource.info('Cleaned old files from install path.');
        }
    }

    private getBaseRetryDeletePath(basePath: string, baseUnpackPath: string, pkg: Package): string | undefined {
        if (pkg.retryDeletePath) {
            return path.join(basePath, pkg.retryDeletePath);
        }
        if (basePath !== baseUnpackPath) {
            return baseUnpackPath;
        }
    }

    private async maybeDownloadPackageAsync(pkg: Package, status: Status): Promise<boolean> {
        // TODO: add config setting to force download
        let shouldDownload = !await this.doesPackageTestPathExistAsync(pkg);
        if (shouldDownload) {
            await this.downloadPackageAsync(pkg, status);
        } else {
            traceSource.info(`Skipping package '${pkg.description}' (already downloaded).`);
        }

        this.stats[pkg.code].didDownload = shouldDownload;
        return shouldDownload;
    }

    private async downloadPackageAsync(pkg: Package, status: Status): Promise<void> {
        traceSource.info(`Downloading package '${pkg.description}' `);

        status.setMessage('Finishing VS Live Share installation (downloading)...');

        pkg.tmpFile = await this.createTempFile(pkg);

        await this.downloadFileAsync(pkg.url, pkg);
        traceSource.info('Download complete.');
    }

    private async downloadFileAsync(urlString: string, pkg: Package): Promise<void> {
        if (!pkg.tmpFile || pkg.tmpFile.fd === 0) {
            throw new PackageError('Temporary package file unavailable', pkg);
        }

        try {
            // The _workbench.downLoadResource API returns the client folder in headless mode
            // which won't work give that path will not exist on the remote system or container.
            // As a result, we need to test for the existence of the location and fall back to alternate
            // logic if the returned folder does not exist.
            if (await ExtensionUtil.isCommandDefined('_workbench.downloadResource')) {
                const location = <vscode.Uri> await vscode.commands.executeCommand('_workbench.downloadResource', vscode.Uri.parse(urlString));
                if (await fileAccess.existsAsync(location.fsPath)) {
                    this.stats[pkg.code].vscodeDownload = true;
                    fileAccess.copyFileSync(location.fsPath, pkg.tmpFile.name);
                    let data = await fileAccess.readFile(pkg.tmpFile.name);
                    this.ensurePkgHashMatches(data, pkg);
                } else {
                    this.stats[pkg.code].vscodeDownload = false;
                }
            } else {
                this.stats[pkg.code].vscodeDownload = false;
            }
            // Fallback
            if (this.stats[pkg.code].vscodeDownload === false) {
                const data = await download(urlString, { followRedirect: true, useElectronNet: false });
                this.ensurePkgHashMatches(data, pkg);
                fileAccess.writeFileSync(pkg.tmpFile.name, data);
            }
        } catch (err) {
            throw new PackageError(`Response error: ${err.message || 'NONE'}`, pkg, err);
        }
    }

    private ensurePkgHashMatches(data: Buffer, pkg: Package) {
        let hash = crypto.createHash('sha256').update(data).digest('hex');
        // The hash check is used for file integrity; the file contents are not secret, so a timing attack is not a concern.
        let hasMatch = hash === pkg.checksum; // tslint:disable-line:possible-timing-attack
        this.stats[pkg.code].checksumPass = hasMatch;
        if (!hasMatch) {
            throw new PackageError('Checksum does not match for ' + pkg.description, pkg);
        }
    }

    private createTempFile(pkg: Package) {
        return new Promise<tmp.SynchrounousResult>((resolve, reject) => {
            tmp.file({ prefix: 'package-' }, (err, tmpPath, fd, cleanupCallback) => {
                if (err) {
                    return reject(new PackageError('Error from tmp.file', pkg, err));
                }
                resolve(<tmp.SynchrounousResult>{ name: tmpPath, fd: fd, removeCallback: cleanupCallback });
            });
        });
    }

    private doesPackageTestPathExistAsync(pkg: Package): Promise<boolean> {
        const testPath = this.getPackageTestPath(pkg);
        if (testPath) {
            return util.fileExistsAsync(testPath);
        } else {
            return Promise.resolve(false);
        }
    }

    private getPackageTestPath(pkg: Package): string {
        if (pkg.installTestPath) {
            return path.join(ExtensionUtil.getGlobalStoragePath(), pkg.installTestPath);
        } else {
            return null;
        }
    }

    private async installPackageAsync(pkg: Package, status?: Status): Promise<boolean> {
        if (!pkg.tmpFile) {
            // Download of this package was skipped, so there is nothing to install
            return false;
        }

        traceSource.info(`Installing package '${pkg.description}'`);
        status.setMessage('Finishing VS Live Share installation (installing)...');

        try {
            if (pkg.tmpFile.fd === 0) {
                throw new PackageError('Downloaded file unavailable', pkg);
            }

            const baseInstallPath = PackageManager.getBaseInstallPath(pkg);
            const baseUnpackPath = PackageManager.getBaseUnpackPath(baseInstallPath, pkg);
            const baseRetryDeletePath = this.getBaseRetryDeletePath(baseInstallPath, baseUnpackPath, pkg);

            await PackageManager.ensureCleanInstallPath(baseRetryDeletePath);

            const baseFilesPreUnpack = PackageManager.getAllFilesSync(baseUnpackPath);
            this.stats[pkg.code].totalBaseFilesPreUnpack = baseFilesPreUnpack.length;

            await this.unpackDownloadedPackage(pkg, baseUnpackPath);

            const baseFilesPostUnpack = this.getAllRelativeFilesSync(baseUnpackPath);
            const filesAdded = baseFilesPostUnpack.length - baseFilesPreUnpack.length;
            this.stats[pkg.code].totalBaseFilesPostUnpack = baseFilesPostUnpack.length;
            this.stats[pkg.code].totalFilesExtracted = filesAdded;

            if (pkg.packageRootPath) {
                const baseFilesPreMove = PackageManager.getAllFilesSync(baseInstallPath);
                this.stats[pkg.code].totalBaseFilesPreMove = baseFilesPreMove.length;

                PackageManager.moveUnpackedPackageFiles(pkg,
                    (cwd: string) => {
                        return PackageManager.getAllFilesSync(cwd);
                    },
                    (sourcePath: string, targetPath: string) => {
                        util.moveElseThrowSync(sourcePath, targetPath);
                    });

                const baseFilesPostMove = PackageManager.getAllFilesSync(baseInstallPath);
                this.stats[pkg.code].totalBaseFilesPostMove = baseFilesPostMove.length;
                this.stats[pkg.code].totalFileMovedOffset = baseFilesPreMove.length - baseFilesPostMove.length;
            }

            traceSource.info('Finished installing.');
        } catch (err) {
            // If anything goes wrong with unzip, make sure we delete the test path (if there is one)
            // so we will retry again later
            const testPath = this.getPackageTestPath(pkg);
            if (testPath) {
                await fileAccess.unlinkAsync(testPath).catch((err) => { });
            }

            throw err;
        }
        finally {
            // Clean up temp file
            pkg.tmpFile.removeCallback();
        }

        return true;
    }

    private async unpackDownloadedPackage(pkg: Package, baseUnpackPath: string) {
        if (pkg.url.endsWith('zip')) {
            await this.unzipPackageAsync(pkg, baseUnpackPath);
        } else if (pkg.url.endsWith('tar.gz')) {
            await this.untarPackageAsync(pkg, baseUnpackPath);
        }

        traceSource.verbose('Extracted packed files');
    }

    private async unzipPackageAsync(pkg: Package, baseUnpackPath: string): Promise<void> {
        const tempProcess = (process as any);
        const noAsar = tempProcess.noAsar;
        tempProcess.noAsar = true;
        try {
            await fileAccess.ensureDirAsync(baseUnpackPath);
            await extractZip(pkg.tmpFile.name, { dir: baseUnpackPath });
        } finally {
            tempProcess.noAsar = noAsar;
        }
    }

    private async untarPackageAsync(pkg: Package, baseUnpackPath: string) {
        try {
            await fileAccess.ensureDirAsync(baseUnpackPath);
            await tar.extract({ cwd: baseUnpackPath, file: pkg.tmpFile.name }, pkg.packageRootPath ? [pkg.packageRootPath] : []);
        } catch (err) {
            throw new PackageError('Zip File Error:' + err.code || '', pkg, err);
        }
    }

    public static moveUnpackedPackageFiles(pkg: Package, getAllFiles: (cwd: string) => string[], moveFn: (sourcePath: string, targetPath: string) => void) {
        const baseInstallPath = PackageManager.getBaseInstallPath(pkg);
        const baseUnpackPath = PackageManager.getBaseUnpackPath(baseInstallPath, pkg);
        let files = getAllFiles(baseUnpackPath);
        files.forEach((f) => {
            let targetPath = path.join(baseInstallPath, path.basename(f));
            moveFn(f, targetPath);
        });

        traceSource.info(`Moved package files.`);
    }

    public static getAllFilesSync(cwd: string) {
        return glob.sync('**/*', { cwd, nodir: true, absolute: true, dot: true });
    }

    private getAllRelativeFilesSync(cwd: string) {
        return glob.sync('**/*', { cwd, nodir: true, absolute: false, dot: true });
    }
}
