'use strict';

import * as vscode from 'vscode';
import * as os from 'os';
import * as path from 'path';
import { fileAccess, IFileSystemStats } from '@vs/vscode-command-framework';

export function getSupportedRuntimeIdentifiers(): string[] {
    switch (os.platform()) {
        case 'win32': return ['win7-x86', 'win', 'win-x86'];
        case 'darwin': return ['osx.10.10-x64', 'osx', 'osx-x64', 'unix'];
        case 'linux': return ['linux-x64', 'unix'];
        default: return [];
    }
}

/**
 * Async function to get file or directory stats.
 *
 * @param fileOrDir File or directory path to get stats for.
 * @returns File or directory stats.
 */
export const statAsync = (fileOrDir: string): Promise<IFileSystemStats> => {
    return new Promise<IFileSystemStats>((resolve, reject) => {
        fileAccess.stat(fileOrDir, (err, stats) => err ? reject(err) : resolve(stats));
    });
};

/**
 * Async function to get the immediate children of a directory.
 */
export const readdirAsync = (dir: string): Promise<string[]> => {
    return new Promise<string[]>((resolve, reject) => {
        fileAccess.readdir(dir, (err, children) => err ? reject(err) : resolve(children));
    });
};

/**
 * Searches for files in a directory that pass a given filter.
 *
 * @param root Returned results are paths relative to this root.
 * @param dir Starting directory for the search.
 * @param filter Optional callback to filter the files.
 */
export const findFilesAsync = async (
    root: string,
    dir: string,
    filter?: (path: string) => boolean
): Promise<string[]> => {
    let results: string[] = [];

    let children: string[] = [];
    try {
        children = await readdirAsync(dir);
    } catch (e) {
        // Skip a directory if it couldn't be read.
    }

    for (let child of children) {
        const childPath = path.join(dir, child);

        let childStat: IFileSystemStats;
        try {
            childStat = await statAsync(childPath);
        } catch (e) {
            // Skip a child if it couldn't be read.
            continue;
        }

        if (childStat.isDirectory()) {
            const childResults = await findFilesAsync(root, childPath, filter);
            results = results.concat(childResults);
        } else {
            const childRelativePath = path.relative(root, childPath);
            if (!filter || filter(childRelativePath)) {
                results.push(childRelativePath);
            }
        }
    }

    return results;
};

/**
 * Function to check whether value is a Date.
 *
 * @param date Value to check the type for.
 * @returns Whether the date is of type of date.
 */
export const isDate = (date: any): boolean => {
    return Object.prototype.toString.call(date) === '[object Date]';
};

/**
 * Function to get retrospective timestamp age in ms.
 *
 * @param timestamp Timestamp to check age for.
 * @returns Age in milliseconds.
 */
export const getTimestampAge = (timestamp: any): number => {
    const date = (isDate(timestamp))
        ? timestamp
        : new Date(timestamp);

    return Date.now() - date.valueOf();
};

/**
 * Function to sleep for a certain amount of milliseconds without blocking main thread.
 *
 * @param delay Amount of milliseconds to sleep for.
 * @returns Promise that will be resolved after `delay` milliseconds.
 */
export const sleepAsync = (delay: number): Promise<void> => {
    return new Promise((resolve) => {
        setTimeout(resolve, delay); // tslint:disable-line:no-string-based-set-timeout
    });
};

/**
 * Async function to get file modification time.
 *
 * @param filePath File path to get modification time for.
 * @returns Date string when the file was modificated.
 */
export const getModificationTime = async (filePath: string): Promise<Date> => {
    const fileStats: IFileSystemStats = await statAsync(filePath);
    return fileStats.mtime;
};

export function fileExistsAsync(filePath: string): Promise<boolean> {
    return new Promise<boolean>((resolve) => {
        fileAccess.stat(filePath, (err, stats) => {
            if (stats && stats.isFile()) {
                resolve(true);
            } else {
                resolve(false);
            }
        });
    });
}

/**
 * Copies a file and then calls stat to check if the file was copied.
 * Throws if the file didn't get copied.
 */
export function copyElseThrowSync(sourcePath: string, targetPath: string) {
    fileAccess.copySync(sourcePath, targetPath);
    // Check to see if the file was copied - we've seen cases where it's not.
    fileAccess.statSync(targetPath);
}

/**
 * Moves a file and then calls stat to check if the file was moved.
 * Throws if the file didn't get moved.
 */
export function moveElseThrowSync(sourcePath: string, targetPath: string) {
    fileAccess.renameSync(sourcePath, targetPath);
    // Check to see if the file was moved - we've seen cases where it's not
    // (will throw if not found) and then check that it has content.
    // Check that it has content
    const fileStats = fileAccess.statSync(targetPath);
    if (fileStats.size <= 0) {
        throw new Error(`Setup of package files failed verification tests. Source: ${sourcePath}, target: ${targetPath}`);
    }
}

export enum PromiseStatus {
    Pending,
    Fulfilled,
    Rejected,
    NotAPromise
}

/**
 * Util to get promise status.
 * @param p Promise to check the status on.
 */
export const getPromiseState = async (p: Promise<any>): Promise<PromiseStatus> => {
    if (!p) {
        return PromiseStatus.NotAPromise;
    }
    const t = {};
    return await Promise.race([p, t]).then(
        (v) => {
            return (v === t)
                ? PromiseStatus.Pending
                : PromiseStatus.Fulfilled;
        },
        () => PromiseStatus.Rejected);
};

/**
 * Check if the cancellation token source is still active.
 * @param source Cancellation token source to check.
 */
export const isActiveCancellationTokenSource = (source: vscode.CancellationTokenSource): boolean => {
    return !!(source && !source.token.isCancellationRequested);
};

/**
 * Function to read all derictories in a folder.
 * @param source The folder path.
 * @returns list of the folders.
 */
export const getDirectoriesAsync = async (source: string) => {
    const directoryContents = await fileAccess.readdir(source);

    return directoryContents
            .map((name) => {
                return path.join(source, name);
            })
            .filter((folderPath: string) => {
                const stats = fileAccess.lstatSync(folderPath);

                return stats.isDirectory();
            });
};

export class UriUtils {
    public static areUrisEqual(uri1: vscode.Uri, uri2: vscode.Uri): boolean {
        if (!uri1 || !uri2) {
            return;
        }

        const path1 = uri1.path || '';
        const path2 = uri2.path || '';
    
        /**
         * This function `on purpose` checks only for these 3 attriburtes since
         * it is used for empty workspace fileOpen dialog and the dialog `Uris` return only these 3,
         * if you consider adding more checks, you may break the empty workspace openFile dialog logic (!).
         */
        const isPathEqual = (path1.toLowerCase() === path2.toLowerCase());
        const isFsPathEqual = (uri1.fsPath === uri2.fsPath);
        const isSchemeEqual = (uri1.scheme === uri2.scheme);
    
        return isPathEqual && isFsPathEqual && isSchemeEqual;
    }
}

/**
 * Polls a predicate function until it either resolves `true`, or the max number of attempts is reached (resolves `false`).
 *
 * @param predicate A function that returns `true` if polling should complete
 * @param interval Polling interval (ms)
 * @param maxAttempts How many polling attempts should occur before giving up
 */
export async function poll(predicate: () => boolean, interval: number = 1000, maxAttempts: number = 1000): Promise<boolean> {
    return new Promise<boolean>((resolve, reject) => {
        let count = 0;
        const intervalId = setInterval(() => {
            if (count > maxAttempts) {
                clearInterval(intervalId);
                resolve(false);
            }

            const result = predicate();
            if (result) {
                clearInterval(intervalId);
                resolve(true);
            }

            count++;
        }, interval);
    });
}