import * as net from 'net';
import { IGuestChannelService } from '../_new_/abstractions/Interfaces';
import { IDependencies } from '../_new_/IDependencies';
import { CancellationToken } from 'vscode';
import { Signal } from '@vs/vso-rpc';
import { getPipePath } from '../utils/getPipePath';
import { Disposable } from 'vscode-jsonrpc';

import {
    vsls,
} from '@vs/liveshare-core';

const pipeNamePrefix: string = 'IHostChannel.';
export class GuestChannelService implements IGuestChannelService {
    private portForwardingService: vsls.PortForwardingService;
    private isActive: boolean;
    private pipes: Map<string, Signal<string>>;
    private listeners: Array<Disposable> = new Array<Disposable>();

    public constructor(context: IDependencies) {
        this.portForwardingService = context.portForwardingService();
    }

    public async init(): Promise<void> {
        if (this.isActive) {
            return;
        }

        this.listeners.push(this.portForwardingService.onPipeSharingStarted(this.startSharingPipe));
        this.listeners.push(this.portForwardingService.onPipeSharingStopped(this.stopSharingPipe));
        this.isActive = true;
    }

    /**
     * Connects to a pipe being shared from a LiveShare client
     * @param channelName The channel to connect to
     * @param cancellationToken A cancellation token
     */
    public async connectToChannelAsync(channelName: string, cancellationToken?: CancellationToken): Promise<net.Socket | null> {
        if (!this.isActive) {
            return;
        }

        if (!this.pipes) {
            this.pipes = new Map<string, Signal<string>>();
            const pipes = await this.portForwardingService.getSharedPipesAsync(cancellationToken);
            if (pipes) {
                pipes.forEach(pipe => {
                    const channel = this.getChannelNameFromSession(pipe.sessionName);
                    if (channel) {
                        let pipeSignal = this.pipes.get(channel); 
                        if (!pipeSignal) {
                            pipeSignal = new Signal<string>();
                            this.pipes.set(channel, pipeSignal);
                        }

                        pipeSignal.complete(getPipePath(pipe.destinationPipeName));
                    }
                });
            }
        }

        let pipeNameSignal = this.pipes.get(channelName);
        if (!pipeNameSignal) {
            this.pipes.set(channelName, new Signal<string>());
            pipeNameSignal = this.pipes.get(channelName);
        }

        const pipePath = await pipeNameSignal.withCancellation(cancellationToken);

        const result = new Signal<net.Socket>();
        const stream: net.Socket = net.connect({
            path: pipePath,
            readable: true
        }, () => {
            result.complete(stream);
        });

        return result.withCancellation(cancellationToken);
    }

    public dispose(): Promise<void> {
        this.listeners.forEach((listener) => listener.dispose());
        if (this.pipes) {
            this.pipes.clear();
        }
        return Promise.resolve();
    }

    private startSharingPipe = async (e: vsls.PipeSharingStartedEventArgs): Promise<void> => {
        const channelName = this.getChannelNameFromSession(e.pipe.sessionName);
        if (!channelName) {
            return;
        }

        const pipePath = getPipePath(e.pipe.destinationPipeName);
        if (this.pipes.has(channelName)) {
            const pipeSignal = this.pipes.get(channelName);
            pipeSignal.complete(pipePath);
        } else {
            const pipeSignal = new Signal<string>();
            pipeSignal.complete(pipePath);
            this.pipes.set(channelName, pipeSignal);
        }
    }

    private stopSharingPipe = async (e: vsls.PipeSharingStoppedEventArgs): Promise<void> => {
        const channelName = this.getChannelNameFromSession(e.pipe.sessionName);
        if (this.pipes.get(channelName)) {
            this.pipes.delete(channelName);
        }
    }

    private getChannelNameFromSession(sessionName: string): string {
        return sessionName && sessionName.startsWith(pipeNamePrefix) ? sessionName.substring(pipeNamePrefix.length) : '';
    }
}