import * as vscode from 'vscode';
import { TraceSource } from '@vs/vso-logging';

import { vsls } from '@vs/liveshare-core';

import { IGuestTrackerManager } from '../abstractions/Interfaces';
import { INotificationUtil } from '../abstractions/INotificationUtil';
import { IBrowserUtil } from '../util/BrowserUtil';

import {
    ITelemetry,
    ITelemetryEvent,
} from '@vs/vso-telemetry';

import {
    CollaboratorChangedEventArgs,
    TelemetryEventNames,
    TelemetryPropertyNames,
    ISessionContext,
} from '@vs/liveshare-core';

export class GuestTrackerManager implements IGuestTrackerManager {
    private static readonly OTHER_ID = 4;
    private alreadyDisposed: boolean = false;
    private peopleDidJoin: boolean = false;
    private telemetryEvent: ITelemetryEvent;
    private collaboratorsChangedRegistration: vscode.Disposable;

    constructor (
        private sessionContext: ISessionContext,
        private telemetry: ITelemetry,
        private notificationUtil: INotificationUtil,
        private browserUtil: IBrowserUtil,
        private trace: TraceSource) {
    }

    public shouldShow(): boolean {
        //return !this.peopleDidJoin;
        // Disabling for the time being
        return false;
    }

    public async init(): Promise<void> {
        this.alreadyDisposed = false;

        this.collaboratorsChangedRegistration = this.sessionContext.onCollaboratorChanged(this.registerUser);

        this.telemetryEvent = this.telemetry.startTimedEvent(TelemetryEventNames.ZEROUSER_SESSION);
    }

    public async dispose(): Promise<void> {
        if (this.collaboratorsChangedRegistration) this.collaboratorsChangedRegistration.dispose();

        const shouldShow = this.shouldShow();

        if (!this.alreadyDisposed && shouldShow) {
            try {
                await this.showNotification(this.telemetryEvent);
            } catch (e) {
                this.trace.error('Error in disposing `GuestTrackerManager`: ' + e);
            }
        }

        this.alreadyDisposed = true;
        this.peopleDidJoin = false;
        this.telemetryEvent = null;
    }

    private registerUser = (e: CollaboratorChangedEventArgs) => {
        if (e && (e.changeType === vsls.WorkspaceSessionChangeType.Joined)) {
            this.peopleDidJoin = true;
        }
    }

    private async showNotification(telemetryEvent: ITelemetryEvent) {
        const options = {
            placeHolder: 'Did your Live Share collaboration session work well?',
            ignoreFocusOut: false,

        };
        const values = [
            { label: 'Yep!', description: 'I’m just testing it out, and plan to use it again.', id: 1 },
            { label: 'Nope!', description: 'No guests were able to successfully join.', id: 2 },
            { label: 'Nope!', description: 'I wasn’t sure what to do after sharing.', id: 3 },
            { label: 'Nope!', description: 'I ran into an issue and would like to report it', id: 4 }
        ];

        const result = await this.notificationUtil.showQuickPick(values, options);

        const reason = result ? `${result.label} ${result.description}` : 'Ignored';

        telemetryEvent.addProperty(TelemetryPropertyNames.ZEROUSER_SESSION_REASON, reason);
        telemetryEvent.send();

        if (result.id === GuestTrackerManager.OTHER_ID) {
            this.browserUtil.openBrowser('https://aka.ms/vsls/share-issue');
        }
    }
}