import * as vscode from 'vscode';
import * as path from 'path';
import WelcomePageHTMLProvider from './welcomePageHTMLProvider';
import * as config from '../config';

import { TelemetryEvent } from '@vs/vso-telemetry';
import { JoinPreReloadCommandOptions } from '../_new_/abstractions/IJoinPreReloadCommandOptions';
import { ShareCommandOptions } from '../_new_/commands/ShareCommandOptions';

import { EXTENSION_ROOT_PATH } from '../constants';
import * as semver from 'semver';

import {
    CommandId,
    SessionContext,
    SessionState,
    SessionStateChangedEventArgs,
    TelemetryEventNames,
    TelemetryPropertyNames,
    sessionStateTracker,
    userAuthStateTracker,
    workspaceSessionInfoTracker
} from '@vs/liveshare-core';

let welcomePanel: any;
let welcomePageHTMLProvider: WelcomePageHTMLProvider;

export const showWelcomeNotification = async () => {
    // make sure the `what's new` notification is not shown
    await config.save(config.Key.whatsNewUri, '');

    new TelemetryEvent(TelemetryEventNames.WELCOME_PAGE_TOAST_SHOWN).send();

    const getStartedButton = { title: 'Get started' };
    const result = await vscode.window.showInformationMessage(
        'VS Live Share installed! You can now collaboratively edit and debug with your team in real time.',
        getStartedButton
    );

    const welcomePageToastInteractionTelemetryEvent = new TelemetryEvent(TelemetryEventNames.WELCOME_PAGE_TOAST_SHOWN_INTERACTION);

    let showedPage = false;
    if (result && (result.title === getStartedButton.title)) {
        // show the welcome page
        await showWelcomePage(WelcomePageSource.Install);
        welcomePageToastInteractionTelemetryEvent.addProperty('openedPage', true);
        showedPage = true;
    } else {
        welcomePageToastInteractionTelemetryEvent.addProperty('openedPage', false);
    }

    welcomePageToastInteractionTelemetryEvent.addProperty(TelemetryPropertyNames.SHOWED_INITIAL_INSTALL_INFO_PAGE, showedPage);
    welcomePageToastInteractionTelemetryEvent.send();
};

export const showWelcomePage = async (source: WelcomePageSource) => {
    // show the welcome page
    const welcomePageShownTelemetryEvent = new TelemetryEvent(TelemetryEventNames.WELCOME_PAGE_SHOWN);
    welcomePageShownTelemetryEvent.addProperty('source', source);
    welcomePageShownTelemetryEvent.addProperty('state', SessionState[sessionStateTracker.State]);

    // Do not show welcome page for install in VSO
    if (semver.gte(semver.coerce(vscode.version), '1.39.0') 
        && vscode.env.uiKind === vscode.UIKind.Web
        && source === WelcomePageSource.Install) {
        return;
    }

    // Check if WebviewPanel API exists
    const window: any = vscode.window;
    if (typeof window.createWebviewPanel === 'function') {
        welcomePageShownTelemetryEvent.addProperty('type', 'web-view');
        await showWebViewWelcomePage(window, source);
    } else {
        // Otherwise fallback to TextDocumentContentProvider
        // This fallback can be removed when we no longer support
        // older versions of VSCode without WebviewPanel API
        welcomePageShownTelemetryEvent.addProperty('type', 'html-preview');
        await showHTMLPreviewWelcomePage();
    }

    welcomePageShownTelemetryEvent.send();

    return true;
};

export enum WelcomePageSource {
    Help = 'Help',
    Install = 'Install',
    Sharing = 'Sharing',
    FirstShare = 'FirstShare',
    FirstJoin = 'FirstJoin'
}

function getJoinUri(): string {
    const isShared = (sessionStateTracker.State === SessionState.Shared);
    return (isShared && workspaceSessionInfoTracker.workspaceSessionInfo)
            ? workspaceSessionInfoTracker.workspaceSessionInfo.joinUri
            : null;
}

async function showHTMLPreviewWelcomePage(): Promise<void> {
    const settings = vscode.workspace.getConfiguration();
    const previewUri = vscode.Uri.parse('vsliveshare-welcome-page://authority/vsliveshare-welcome-page');

    if (!welcomePageHTMLProvider) {
        welcomePageHTMLProvider = new WelcomePageHTMLProvider();
        welcomePageHTMLProvider.isPostReloadJoin = !!settings.get(CommandId.joinWorkspaceIdSettingName);
        welcomePageHTMLProvider.joinUri = getJoinUri();
        welcomePageHTMLProvider.sessionState = sessionStateTracker.State;
        welcomePageHTMLProvider.sessionHigherState = sessionStateTracker.HigherState;
        welcomePageHTMLProvider.isWebview = false;
        welcomePageHTMLProvider.isAuthenticated = userAuthStateTracker.IsSignedIn;
        welcomePageHTMLProvider.hasCollaborators = SessionContext.hasCollaborators;
        vscode.workspace.registerTextDocumentContentProvider('vsliveshare-welcome-page', welcomePageHTMLProvider);

        // Session state changes
        const onSessionStateChanged = async (e: SessionStateChangedEventArgs) => {
            // The session state has changed, update welcome page
            welcomePageHTMLProvider.isPostReloadJoin = !!settings.get(CommandId.joinWorkspaceIdSettingName);
            welcomePageHTMLProvider.joinUri = getJoinUri();
            welcomePageHTMLProvider.sessionState = e.newState;
            welcomePageHTMLProvider.sessionHigherState = sessionStateTracker.HigherState;
            welcomePageHTMLProvider.sessionAction = e.newAction;
            welcomePageHTMLProvider.isAuthenticated = userAuthStateTracker.IsSignedIn;
            welcomePageHTMLProvider.update(previewUri);
        };
        sessionStateTracker.onStateChanged(onSessionStateChanged);

        // Collaborators joined
        const onCollaboratorsJoined = async () => {
            welcomePageHTMLProvider.hasCollaborators = SessionContext.hasCollaborators;
            welcomePageHTMLProvider.update(previewUri);
        };
        SessionContext.onCollaboratorsJoined(onCollaboratorsJoined);
    }

    await vscode.commands.executeCommand('vscode.previewHtml', previewUri, vscode.ViewColumn.One);
}

async function showWebViewWelcomePage(window: any, source: WelcomePageSource): Promise<void> {
    if (welcomePanel) {
        // Welcome panel already exists reveal it
        welcomePanel.reveal(vscode.ViewColumn.One);
        return;
    }

    if (!welcomePageHTMLProvider) {
        welcomePageHTMLProvider = new WelcomePageHTMLProvider();
    }

    const welcomePagePath = path.join(EXTENSION_ROOT_PATH, './out/prod/welcomePage');
    welcomePanel = window.createWebviewPanel('vsliveshare-welcome-page', 'vsliveshare-welcome-page', vscode.ViewColumn.Active, {
        enableScripts: true,
        // Restrict the webview to only load content from the `welcomePage` directory.
        localResourceRoots: [
            vscode.Uri.file(welcomePagePath)
        ]
    });

    const settings = vscode.workspace.getConfiguration();

    welcomePageHTMLProvider.joinUri = getJoinUri();
    welcomePageHTMLProvider.sessionState = sessionStateTracker.State;
    welcomePageHTMLProvider.sessionHigherState = sessionStateTracker.HigherState;
    welcomePageHTMLProvider.isWebview = true;
    welcomePageHTMLProvider.isFirstTimeJoin = (source === WelcomePageSource.FirstJoin);
    welcomePageHTMLProvider.isPostReloadJoin = !!settings.get(CommandId.joinWorkspaceIdSettingName);
    welcomePageHTMLProvider.isAuthenticated = userAuthStateTracker.IsSignedIn;
    welcomePageHTMLProvider.hasCollaborators = SessionContext.hasCollaborators;
    welcomePanel.webview.html = welcomePageHTMLProvider.provideTextDocumentContent(null);

    try {
        vscode.commands.executeCommand('workbench.view.extension.liveshare');
    } catch {
        // The command isn't available in the end-user's version of VS Code,
        // and there's no reasonable workaround. So just silently no-op.
    }

    welcomePanel.webview.onDidReceiveMessage(function(message: any) {
        switch (message.command) {
            case 'copyUrl':
                new TelemetryEvent(TelemetryEventNames.WELCOME_PAGE_COPY_CLICKED).send();
                vscode.commands.executeCommand('liveshare.collaboration.link.copy');
                return;
            case 'onClick':
                new TelemetryEvent(TelemetryEventNames.WELCOME_PAGE_LINK_CLICKED)
                    .addProperty(TelemetryPropertyNames.WELCOME_PAGE_LINK, message.text)
                    .send();
                return;
            case 'shareWithYourself':
                new TelemetryEvent(TelemetryEventNames.WELCOME_PAGE_LINK_CLICKED)
                    .addProperty(TelemetryPropertyNames.WELCOME_PAGE_LINK, message.text)
                    .send();

                const joinCommandOptions: JoinPreReloadCommandOptions = { link: getJoinUri(), newWindow: true };
                vscode.commands.executeCommand(`${config.get<string>(config.Key.commandPrefix)}.join`, joinCommandOptions);
                return;
            case 'signIn':
                new TelemetryEvent(TelemetryEventNames.WELCOME_PAGE_LINK_CLICKED)
                    .addProperty(TelemetryPropertyNames.WELCOME_PAGE_LINK, message.text)
                    .send();
                const shareCommandOptions: ShareCommandOptions = {};
                vscode.commands.executeCommand('liveshare.start', shareCommandOptions);
                return;
            case 'startFromWelcomePage':
                vscode.commands.executeCommand('liveshare.startFromWelcomePage');
                return;
            default:
                return;
        }
    });

    let disposables: vscode.Disposable[] = [];

    // Session state changes
    const onSessionStateChanged = async (e: SessionStateChangedEventArgs) => {
        // The session state has changed, update welcome page
        welcomePageHTMLProvider.isPostReloadJoin = !!settings.get(CommandId.joinWorkspaceIdSettingName);
        welcomePageHTMLProvider.joinUri = getJoinUri();
        welcomePageHTMLProvider.sessionState = e.newState;
        welcomePageHTMLProvider.sessionHigherState = sessionStateTracker.HigherState;
        welcomePageHTMLProvider.sessionAction = e.newAction;
        welcomePageHTMLProvider.isAuthenticated = userAuthStateTracker.IsSignedIn;
        welcomePanel.webview.html = welcomePageHTMLProvider.provideTextDocumentContent(null);
    };

    disposables.push(sessionStateTracker.onStateChanged(onSessionStateChanged));

    // Collaborators joined
    const onCollaboratorsJoined = async () => {
        welcomePageHTMLProvider.hasCollaborators = SessionContext.hasCollaborators;
        welcomePanel.webview.html = welcomePageHTMLProvider.provideTextDocumentContent(null);
    };

    disposables.push(SessionContext.onCollaboratorsJoined(onCollaboratorsJoined));

    welcomePanel.onDidDispose(() => {
        const welcomePageDismissedTelemetryEvent = new TelemetryEvent(TelemetryEventNames.WELCOME_PAGE_DISMISSED);
        for (const disposable of disposables) {
            disposable.dispose();
        }
        disposables = [];

        welcomePanel = null;
        welcomePageDismissedTelemetryEvent.send();
    });
}
