import { CommandBase, ICommandContext } from '@vs/vscode-command-framework';

import {
    IInittableDisposableManager,
    initDisposableManager
} from '@vs/liveshare-core';

/**
 * !Attention!
 * 
 * With the new commands infrastructure we favor `composition` over `inheritance`
 * so if you trying to add more methods to this class, think twice. This method
 * is mean to have just `postSetupManagers` list and `invokePostSetupManagers`
 * method to invoke them. Ping `Anthony van der Hoorn` or `Oleg Solomka` if are
 * not sure how to proceed.
 */


export class LiveShareCommandBase extends CommandBase {
    protected postSetupManagers: IInittableDisposableManager[] = [];

    public async invoke(options: any, context: ICommandContext): Promise<any> {
        return true;
    }

    public invokePostSetupManagers(managers: IInittableDisposableManager[] = this.postSetupManagers) {
        return initDisposableManager(managers);
    }
}
