import * as vscode from 'vscode';
import { traceSource as trace, fileAccess } from '@vs/vscode-command-framework';
import { TraceSource } from '@vs/vso-logging';

import * as util from '../../util';
import { PackageManager, Status, PackageError } from '../../packageManager';
import * as path from 'path';
import * as os from 'os';

import { 
    Telemetry,
    TelemetryResult,
    Fault,
    FaultType,
    ITimedEvent,
    TelemetryEvent} from '@vs/vso-telemetry';
import { 
    PathUtil,
    ExtensionUtil,
    TelemetryEventNames,
    TelemetryPropertyNames
} from '@vs/liveshare-core';
import * as glob from 'glob';
import { AcquisitionTelemetryEventNames, AcquisitionTelemetryPropertyNames } from '../../telemetry/acquisitionTelemetry';
import * as lockFile from 'lockfile';
import { createHash } from '../../utils/createHash';
import { EXTENSION_ROOT_PATH } from '../../constants';
import { loadJSON } from '../../utils/loadJSON';
import { IDownloader } from '../IDownloader';
import { staticImplementsDecorator } from '../../utils/staticImplementsDecorator';
import { IDownloaderStatic } from '../IDownlaoderStatic';

// Lock file needs to be OS specific due to headless - already downloaded .NET Core for a different OS can be transferred
const getInstallFilePath = () => path.resolve(ExtensionUtil.context.extensionPath, `install-${os.platform()}.Lock`);
const getLockFilePath = () => path.resolve(ExtensionUtil.context.extensionPath, `externalDeps-${os.platform()}.Lock`);

export enum EnsureRuntimeDependenciesResult {
    Success,
    Failure,
    AlreadyInstalled
}

/**
 * Class used to download the runtime dependencies
 */
@staticImplementsDecorator<IDownloaderStatic>()
export class ExternalDownloader implements IDownloader {
    public constructor(private packageJSON: any) {
    }

    public static async ensureRuntimeDependenciesAsync(extension: vscode.Extension<any>, activationEvent: ITimedEvent): Promise<EnsureRuntimeDependenciesResult> {
        if (!await installFileExistsAsync()) {
            const downloader = new ExternalDownloader(extension.packageJSON);

            return await ExtensionUtil.runWithProgress<EnsureRuntimeDependenciesResult>(
                async (progress: vscode.Progress<{ message: string }>) => {
                    return downloader.installRuntimeDependenciesAsync(progress);
                },
                { title: 'Downloading dependencies' });
        } else {
            return EnsureRuntimeDependenciesResult.AlreadyInstalled;
        }
    }

    public async installRuntimeDependenciesAsync(progress: vscode.Progress<{ message: string }>): Promise<EnsureRuntimeDependenciesResult> {
        const status: Status = {
            setMessage: (text: string) => {
                progress.report({message: text});
            }
        };

        const lockOptions: lockFile.Options = {
            // Consider the lockfile stale if it was created before the last boot.
            stale: os.uptime() * 1000,
        };

        if (lockFile.checkSync(getLockFilePath(), lockOptions)) {
            trace.error('Dependency lock file already exists');
            // Returning failure will prompt the user to repair the installation
            return EnsureRuntimeDependenciesResult.Failure;
        } else {
            try {
                lockFile.lockSync(getLockFilePath(), lockOptions);
            } catch (e) {
                const lockFileFaultEvent = new Fault(AcquisitionTelemetryEventNames.LOCK_FILE_FAULT, FaultType.Error,
                                                              'Failed to lock lock file.', e);
                lockFileFaultEvent.addProperty(AcquisitionTelemetryPropertyNames.ERROR_CODE, e.code);
                lockFileFaultEvent.send();
                lockFile.unlockSync(getLockFilePath());
                lockFile.lockSync(getLockFilePath(), lockOptions);
            }

            trace.info('Installing dependencies for Live Share...');

            let packageManager: PackageManager;
            let installationStage: string;
            let errorMessage = '';
            let result = EnsureRuntimeDependenciesResult.Failure;
            let telemetryEvent = Telemetry.startTimedEvent(AcquisitionTelemetryEventNames.ACQUIRE_DEPS, true);
            let platform: string;
            let architecture: string;

            try {
                installationStage = 'getPlatformInfo';

                platform = os.platform();
                architecture = os.arch();
                packageManager = new PackageManager(platform, architecture, this.packageJSON);

                installationStage = 'downloadPackages';

                await packageManager.downloadPackagesAsync(status);

                installationStage = 'installPackages';
                await packageManager.installPackagesAsync(status);

                installationStage = 'installRuntimeExes';
                ExternalDownloader.installRuntimeSpecificAssets((sourcePath: string, targetPath: string) => {
                    util.copyElseThrowSync(sourcePath, targetPath);
                });

                installationStage = 'touchLockFile';
                await touchInstallFileAsync();

                installationStage = 'completeSuccess';
                result = EnsureRuntimeDependenciesResult.Success;
            } catch (error) {
                if (error instanceof PackageError) {
                    // we can log the message in a PackageError to telemetry as we do not put PII in PackageError messages
                    if (error.innerError) {
                        errorMessage = 'Dependency download failed. ' + error.innerError.toString();
                    } else {
                        errorMessage = 'Dependency download failed. ' + error.message;
                    }

                    if (error.pkg) {
                        telemetryEvent.addProperty(AcquisitionTelemetryPropertyNames.PACKAGE_URL, error.pkg.url);
                        telemetryEvent.addProperty(AcquisitionTelemetryPropertyNames.PACKAGE_CODE, error.pkg.code);
                    }
                } else {
                    // do not log raw errorMessage in telemetry as it is likely to contain PII.
                    errorMessage = 'Dependency download failed. ' + error.toString();
                }

                Telemetry.sendFault(AcquisitionTelemetryEventNames.ACQUIRE_DEPS_FAULT, FaultType.Unknown, errorMessage);

                trace.error(`Failed at stage: ${installationStage} - ${errorMessage}`);
            } finally {
                this.sendDownloadTelemetry(telemetryEvent, installationStage, platform, architecture, (result === EnsureRuntimeDependenciesResult.Success), errorMessage);
                this.sendPackageTelemetry(packageManager);

                status.setMessage('');

                lockFile.unlockSync(getLockFilePath());
            }

            return result;
        }
    }

    public static installRuntimeSpecificAssets(copyFn: (sourcePath: string, targetPath: string) => void): void {
        const dotnetDir = path.join(ExtensionUtil.context.extensionPath, 'dotnet_modules');
        const exesDir = path.join(dotnetDir, 'exes');

        const supportedRIDs = util.getSupportedRuntimeIdentifiers();
        supportedRIDs.forEach(rid => {
            const ridDir = path.join(exesDir, rid);
            const ridDirFiles = glob.sync('**/*', {cwd: ridDir, nodir: true, absolute: true});

            ridDirFiles.forEach(f => {
                const targetPath = path.join(dotnetDir, path.basename(f));
                copyFn(f, targetPath);
            });
        });
    }

    public static async deleteRuntimeDependencies() {
        const deletingDependenciesAction = new TelemetryEvent(TelemetryEventNames.DELETE_RUNTIME_DEPENDENCIES);
        trace.info('Delete runtime dependencies');
        try {
            const downloadLockFilePath = getLockFilePath();
            if (await fileAccess.pathExists(downloadLockFilePath)) {
                trace.info('Download lock file found. Deleting...');
                deletingDependenciesAction.addProperty(TelemetryPropertyNames.DELETE_DEPENDENCIES_DOWNLOAD_FILE, true);
                await fileAccess.remove(downloadLockFilePath);
            }

            const installedLockFilePath = getInstallFilePath();
            if (await fileAccess.pathExists(installedLockFilePath)) {
                trace.info('Installed lock file found. Deleting...');
                deletingDependenciesAction.addProperty(TelemetryPropertyNames.DELETE_DEPENDENCIES_INSTALLED_FILE, true);
                await fileAccess.remove(installedLockFilePath);
            }

            trace.info('Clean dotnet install path');
            deletingDependenciesAction.addProperty(TelemetryPropertyNames.DELETE_DEPENDENCIES_CLEAN_INSTALL_PATH, true);
            const dotnetInstallPath = PackageManager.getDotnetInstallPath();
            await PackageManager.ensureCleanInstallPath(dotnetInstallPath);
            trace.info('Finished cleaning dotnet install path');
        } catch (e) {
            trace.error(`Error deleting runtime dependencies: ${e}`);
            const deleteDependenciesFaultEvent = new Fault(AcquisitionTelemetryEventNames.DELETE_DEPENDENCIES_FAULT, FaultType.Error,
                'Failed to delete dependencies', e);
            deleteDependenciesFaultEvent.correlateWith(deletingDependenciesAction);
            deleteDependenciesFaultEvent.addProperty(AcquisitionTelemetryPropertyNames.ERROR_CODE, e.code);
            deleteDependenciesFaultEvent.send();
        }

        deletingDependenciesAction.send();
    }

    private sendDownloadTelemetry(
        event: ITimedEvent,
        stage: string,
        platform: string,
        arch: string,
        success: boolean,
        errorMessage: string
    ) {
        event.addProperty(AcquisitionTelemetryPropertyNames.INSTALLATION_STAGE, stage);
        event.addProperty(AcquisitionTelemetryPropertyNames.INSTALLATION_PLATFORM, platform);
        event.addProperty(AcquisitionTelemetryPropertyNames.INSTALLATION_ARCH, arch);

        let message = success === true ? 'Dependency download success. ' : errorMessage;
        event.end(success === true ? TelemetryResult.Success : TelemetryResult.IndeterminateFailure, message);
    }

    private sendPackageTelemetry(packageManager: PackageManager) {
        for (let key in packageManager.stats) {
            if (packageManager.stats.hasOwnProperty(key)) {
                const stats = packageManager.stats[key];

                const payload = {};
                this.addPropertyIfExists(payload, AcquisitionTelemetryPropertyNames.DID_DOWNLOAD, stats.didDownload);
                this.addPropertyIfExists(payload, AcquisitionTelemetryPropertyNames.CHECKSUM_PASS, stats.checksumPass);
                this.addPropertyIfExists(payload, AcquisitionTelemetryPropertyNames.VSCODE_DOWNLOAD, stats.vscodeDownload);
                this.addPropertyIfExists(payload, AcquisitionTelemetryPropertyNames.TOTAL_BASE_FILES_PRE_UNPACK, stats.totalBaseFilesPreUnpack);
                this.addPropertyIfExists(payload, AcquisitionTelemetryPropertyNames.TOTAL_BASE_FILES_POST_UNPACK, stats.totalBaseFilesPostUnpack);
                this.addPropertyIfExists(payload, AcquisitionTelemetryPropertyNames.TOTAL_BASE_FILES_PRE_MOVE, stats.totalBaseFilesPreMove);
                this.addPropertyIfExists(payload, AcquisitionTelemetryPropertyNames.TOTAL_BASE_FILES_POST_MOVE, stats.totalBaseFilesPostMove);
                this.addPropertyIfExists(payload, AcquisitionTelemetryPropertyNames.TOTAL_FILES_EXTRACTED, stats.totalFilesExtracted);
                this.addPropertyIfExists(payload, AcquisitionTelemetryPropertyNames.TOTAL_FILES_MOVED_OFFSET, stats.totalFileMovedOffset);

                Telemetry.sendTelemetryEvent(AcquisitionTelemetryEventNames.ACQUIRE_DEPS_PACKAGE, payload);
            }
        }
    }

    private addPropertyIfExists(properties: { [key: string]: string }, propertyName: string, value: any) {
        if (value !== undefined) {
            properties[propertyName] = value.toString();
        }
    }
}

export function installFileExistsAsync(): Promise<boolean> {
    return util.fileExistsAsync(getInstallFilePath());
}

function touchInstallFileAsync(): Promise<void> {
    return fileAccess.writeFileAsync(getInstallFilePath(), '');
}

export async function isInstallCorrupt(traceSource: TraceSource, manifest?: any): Promise<boolean> {
    if (!manifest) {
        manifest = await getCompleteManifest();
    }

    const fileList = Object.keys(manifest);
    const hashTable: Record<string, string> = {};
    const ignoreFiles = ['verson.json', 'internalSettings.json', 'package.json', 'manifest.json', 'externalManifest.json', 'out/prod/extension-prod.js', 'CHANGELOG.md'];
    const ignoreSubstrings = ['runtimeconfig.json', 'deps.json'];

    // Create hashes from current files in extension directory
    await Promise.all(fileList.map(async (fileName) => {
        if (!fileName.length || ignoreFiles.indexOf(fileName) !== -1 || ignoreSubstrings.some(substring => fileName.toLowerCase().includes(substring))) {
            return;
        }
        const hash = await createHash(path.join(EXTENSION_ROOT_PATH, fileName));
        hashTable[fileName] = hash;
    }));

    // Verify that the hashes match those from the manifest
    const allHashesMatch = Object.keys(hashTable).every(fileName => {
        const hashesMatch = (hashTable[fileName] === manifest[fileName]);
        if (!hashesMatch) {
            console.log(`hash mistmatch for file(${fileName}): ${hashTable[fileName]}, ${manifest[fileName]}`);

            Telemetry.sendFault(AcquisitionTelemetryEventNames.INSTALL_FAULT, FaultType.Error, fileName);
            if (traceSource) {
                traceSource.info(`hash mismatch: ${fileName} (${hashTable[fileName]} does not match ${manifest[fileName]} in manifest)`);
            }
        }
        return hashesMatch;
    });

    return !allHashesMatch;
}

export async function getCompleteManifest(): Promise<any> {
    const extensionDir = path.resolve(EXTENSION_ROOT_PATH, './');

    // The external manifest is generated based off of where packages are initially downloaded to.
    // This simulates moving them to their post-install location.
    const packages = PackageManager.getLiveSharePackages();
    const externalManifestPostMove: any = {};
    for (const pkg of packages) {
        const externalManifest = loadJSON(path.resolve(EXTENSION_ROOT_PATH, './externalManifest.json'));
        const pkgFileHashes = externalManifest[pkg.code];
        PackageManager.moveUnpackedPackageFiles(
            pkg,
            (cwd: string) => {
                return Object.keys(pkgFileHashes);
            },
            (sourcePath: string, targetPath: string) => {
                const normalizedTargetPath = PathUtil.convertToForwardSlashes(path.relative(extensionDir, targetPath));
                externalManifestPostMove[normalizedTargetPath] = pkgFileHashes[sourcePath];
            });
    }

    const manifestJSON = loadJSON(path.resolve(EXTENSION_ROOT_PATH, './manifest.json'));
    // The extension directory should contain both the files we ship with the extension (those in manifest), and
    // the downloaded and moved package files (those in externalManifest).
    const completeManifest = Object.assign({}, manifestJSON, externalManifestPostMove);

    // The manifest is generated based off the initial location of the files. On first run, we move
    // run-time specific files around. This simulates that.
    ExternalDownloader.installRuntimeSpecificAssets((sourcePath: string, targetPath: string) => {
        const normalizedSourcePath = PathUtil.convertToForwardSlashes(path.relative(extensionDir, sourcePath));
        const normalizedTargetPath = PathUtil.convertToForwardSlashes(path.relative(extensionDir, targetPath));
        completeManifest[normalizedTargetPath] = completeManifest[normalizedSourcePath];
    });

    return completeManifest;
}