import { vsls } from '@vs/liveshare-core';
import { IHubProxy, IDisposable } from '@vs/vso-signalr-client-proxy';

const invokeHubMethodAsync = 'InvokeHubMethodAsync';

export class HubProxy implements IHubProxy {
    private readonly onHubMethods = new Map<string, (...args: any[]) => void>();
    private readonly onConnectionStateChangedCallbacks: Array<() => Promise<void>> = [];
    private isConnectedValue: boolean;

    constructor(
        private hubName: string,
        private readonly hubConnectionService: vsls.HubConnectionService,
        isConnected: boolean) {
        this.isConnectedValue = isConnected;
        hubConnectionService.onHubMethodNotified((e) => this.onHubMethodNotified(e));
        hubConnectionService.onHubConnectionStateChanged(async (e) => {
            this.isConnectedValue = e.isConnected;
            await Promise.all(this.onConnectionStateChangedCallbacks.map(callback => callback()));
        });
    }

    public onConnectionStateChanged(callback: () => Promise<void>): IDisposable {
        this.onConnectionStateChangedCallbacks.push(callback);
        return {
            dispose: () => {
                const index = this.onConnectionStateChangedCallbacks.indexOf(callback);
                if (index !== -1) {
                    this.onConnectionStateChangedCallbacks.splice(index, 1);
                }                
            }
        };
    }

    public get isConnected(): boolean {
        return this.isConnectedValue;
    }

    public connect(): Promise<void> {
        throw new Error('not implemented');
    }

    public send(methodName: string, ...args: any[]): Promise<void> {
        const hubArgs = [`${this.hubName}.${methodName}`, args];

        return this.hubConnectionService.sendHubMethodAsync(invokeHubMethodAsync, hubArgs);
    }

    public async invoke<T = any>(methodName: string, ...args: any[]): Promise<T> {
        const hubArgs = [`${this.hubName}.${methodName}`, args];
        const result = await this.hubConnectionService.invokeHubMethodAsync(invokeHubMethodAsync, 'object', hubArgs);
        return <T>result;
    }

    public on(methodName: string, newMethod: (...args: any[]) => void): IDisposable {
        const types = new Array(newMethod.length).fill('object');
        const hubMethodName = `${this.hubName}.${methodName}`;
        this.hubConnectionService.registerHubMethodNotifyAsync(hubMethodName, types);
        this.onHubMethods.set(methodName, newMethod);
        return {
            dispose: () => {
                this.hubConnectionService.unregisterHubMethodNotifyAsync(hubMethodName);
            }
        };
    }

    private onHubMethodNotified(e: vsls.HubMethodNotifyEventArgs) {
        if (e.methodName.startsWith(this.hubName)) {
            const methodName = e.methodName.substr(this.hubName.length + 1);
            if (this.onHubMethods.has(methodName)) {
                this.onHubMethods.get(methodName)(...e.parameters);
            }
        }
    }
}
