import * as child_process from 'child_process';

import { CancellationToken } from 'vscode';
import { TraceSource } from '@vs/vso-logging';

import { INotificationUtil } from '../abstractions/INotificationUtil';
import { IAuthenticationFindCodeUtil } from '../abstractions/IAuthenticationFindCodeUtil';

export class AuthenticationFindCodeUtilLinux implements IAuthenticationFindCodeUtil {
    private static readonly userCodeWithExtensionIdRegex = /\[((?:[a-z]{4}\-){3}(?:[a-z]{4}){1}):([a-z0-9-]*)\]/i;

    constructor(
        private notificationUtil: INotificationUtil,
        private trace: TraceSource) {
    }

    public findLoginCode(instanceId: string, cancellationToken?: CancellationToken): Promise<string | undefined> {
        const findLoginCodePromise = new Promise<string | undefined>((resolve, reject) => {

            const findLoginCodeInterval = setInterval(() => {
                child_process.exec(`xprop -id $(xprop -root 32x '\t$0' _NET_ACTIVE_WINDOW | cut -f 2) WM_NAME`, async (err, stdout, stderr) => {
                    if (err || stderr) {
                        // xprop not supported in this Linux distro
                        this.trace.error(err ? err.message : stderr);

                        clearInterval(findLoginCodeInterval);

                        const userCode = await this.notificationUtil.showInputBox({
                            prompt: 'Sign in via the external browser, then paste the user code here.',
                            ignoreFocusOut: true,
                        }, cancellationToken);

                        return resolve(userCode);
                    }

                    const match = stdout.match(AuthenticationFindCodeUtilLinux.userCodeWithExtensionIdRegex);
                    if (match && match.length >= 3) {
                        const [_, userCode, extensionId] = match;

                        if (extensionId === instanceId) {
                            clearInterval(findLoginCodeInterval);
                            return resolve(userCode);
                        }
                    }
                });
            }, 500);

            if (cancellationToken) {
                cancellationToken.onCancellationRequested(() => {
                    clearInterval(findLoginCodeInterval);
                    return resolve(undefined);
                });
            }
        });

        return findLoginCodePromise;
    }
}